def _property_search_raw_run_input_key_allowed(value: object) -> bool:
    key = str(value or "").strip()
    return key in _PROPERTY_SEARCH_RAW_RUN_INPUT_KEYS or key in {
        "adjacent_area_radius_m",
        "adjacent_area_radius_unit",
        "adjacent_area_radius_value",
    } or (
        key.startswith("max_distance_to_")
        and (key.endswith("_m") or key.endswith("_importance"))
    )


def _property_search_delivery_terminal_status(value: object) -> str:
    status = str(value or "").strip().lower()
    return status if status in _PROPERTY_SEARCH_DELIVERABLE_TERMINAL_STATUSES else "processed"


def _property_search_run_preferences_projection(
    preferences: dict[str, object] | None,
) -> dict[str, object]:
    """Return only search-run inputs plus a privacy-safe entitlement marker."""
    source = dict(preferences or {})
    raw_preferences = (
        dict(source.get("raw_preferences") or {})
        if isinstance(source.get("raw_preferences"), dict)
        else {}
    )
    # Project from an allowlist instead of trying to subtract known workspace
    # fields. Compact snapshots may already have flattened raw_preferences,
    # so origin-based filtering can no longer distinguish a search input from
    # private account state such as contact_email.
    merged = {**raw_preferences, **source}
    projected = {
        str(key or "").strip(): value
        for key, value in merged.items()
        if (
            _property_search_raw_run_input_key_allowed(key)
            or str(key or "").strip() in _PROPERTY_SEARCH_DERIVED_RUN_INPUT_KEYS
        )
        and str(key or "").strip() != "property_commercial"
    }
    raw_commercial = (
        dict(merged.get("property_commercial") or {})
        if isinstance(merged.get("property_commercial"), dict)
        else {}
    )
    active_plan_key = str(raw_commercial.get("active_plan_key") or "").strip().lower()
    if active_plan_key:
        safe_commercial: dict[str, object] = {
            "active_plan_key": active_plan_key,
        }
        for entitlement_key in ("status", "active_until"):
            entitlement_value = str(raw_commercial.get(entitlement_key) or "").strip()
            if entitlement_value:
                safe_commercial[entitlement_key] = entitlement_value
        projected["property_commercial"] = safe_commercial
    return projected


def _property_search_run_snapshot_projection(
    snapshot: dict[str, object],
) -> dict[str, object]:
    projected = dict(snapshot or {})
    for key in ("property_search_preferences", "preferences"):
        value = projected.get(key)
        if isinstance(value, dict):
            projected[key] = _property_search_run_preferences_projection(value)
    return projected


def _property_search_run_worker_concurrency() -> int:
    raw_value = str(os.getenv("PROPERTYQUARRY_SEARCH_RUN_WORKER_CONCURRENCY") or "").strip()
    if not raw_value:
        return 4
    try:
        parsed = int(raw_value)
    except Exception:
        return 4
    return max(1, min(parsed, 8))


def _property_search_durable_work_required() -> bool:
    return str(os.environ.get("EA_RUNTIME_MODE") or "dev").strip().lower() == "prod"


def _property_search_work_queue_repository() -> PostgresPropertySearchWorkQueue:
    database_url = _property_search_run_database_url()
    if not database_url:
        raise RuntimeError("property_search_work_database_url_required")
    _require_property_search_run_schema()
    return PostgresPropertySearchWorkQueue(database_url)


_PROPERTY_SEARCH_RUN_WORKER_SEMAPHORE = threading.BoundedSemaphore(_property_search_run_worker_concurrency())


def _property_scout_outbound_notification_min_score() -> float:
    raw_value = str(os.getenv("PROPERTYQUARRY_SCOUT_OUTBOUND_MIN_SCORE") or "").strip()
    if not raw_value:
        return _PROPERTY_SCOUT_OUTBOUND_NOTIFICATION_MIN_SCORE
    try:
        return max(_PROPERTY_SCOUT_OUTBOUND_NOTIFICATION_MIN_SCORE, min(100.0, float(raw_value)))
    except Exception:
        return _PROPERTY_SCOUT_OUTBOUND_NOTIFICATION_MIN_SCORE


def _json_safe_product_payload(value: object) -> object:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, bytes):
        return f"<bytes:{len(value)}>"
    if isinstance(value, google_oauth_service.GoogleWorkspaceAttachment):
        return {
            "attachment_id": str(value.attachment_id or "").strip(),
            "filename": str(value.filename or "").strip(),
            "mime_type": str(value.mime_type or "").strip(),
            "part_id": str(value.part_id or "").strip(),
            "size_bytes": int(value.size_bytes or 0),
            "content_bytes_present": bool(value.content_bytes),
        }
    if isinstance(value, dict):
        return {str(key): _json_safe_product_payload(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_json_safe_product_payload(item) for item in value]
    if hasattr(value, "__dict__"):
        return {str(key): _json_safe_product_payload(item) for key, item in dict(vars(value)).items()}
    return str(value)


def _property_search_platform_aliases() -> tuple[str, ...]:
    return tuple(property_platform_keys())


def _is_known_property_search_platform(platform: str) -> bool:
    return is_known_property_platform(platform)


def _normalize_property_search_platform_inputs(value: object) -> tuple[str, ...]:
    normalized: list[str] = []
    if isinstance(value, (list, tuple, set)):
        candidates = tuple(str(item or "").strip() for item in value)
    elif value is None:
        candidates = ()
    else:
        candidates = (str(value or "").strip(),)
    for raw in candidates:
        current = _normalize_property_search_platform(raw)
        if not current or current in normalized:
            continue
        if current != "all" and not _is_known_property_search_platform(current):
            continue
        normalized.append(current)
    if not normalized:
        return ()
    if any(item == "all" for item in normalized):
        return ("all",)
    return tuple(normalized)


def _property_search_platforms_with_family_toggles(
    selected_platforms: tuple[str, ...],
    preferences: dict[str, object] | None,
) -> tuple[str, ...]:
    normalized = list(_normalize_property_search_platform_inputs(selected_platforms))
    payload = dict(preferences or {})
    country_code = normalize_country_code(resolve_country_code(payload.get("country_code")) or payload.get("country_code"))
    legacy_austria_core = {"willhaben", "immmo", "immoscout_at", "remax_at", "kalandra"}
    if country_code == "AT" and legacy_austria_core.issubset(set(normalized)) and "derstandard_at" not in normalized:
        normalized.append("derstandard_at")
    toggle_platforms = (
        ("include_broker_direct_sources", "broker_direct_at"),
        ("include_shared_housing_sources", "shared_housing_de"),
        ("include_corporate_landlord_sources", "corporate_landlords_de"),
        ("include_municipal_housing_sources", "municipal_housing_de"),
        ("include_cooperative_sources", "cooperatives_de"),
        ("include_furnished_relocation_sources", "furnished_relocation_de"),
        ("include_community_signals", "community_signals_at"),
        ("include_developer_project_signals", "developer_projects_at"),
        ("include_developer_project_signals", "new_build_de"),
        ("include_public_housing_signals", "public_housing_at"),
        ("include_public_housing_signals", "municipal_housing_de"),
        ("include_distressed_sale_signals", "distressed_sales_at"),
        ("include_distressed_sale_signals", "auctions_de"),
        ("enable_auction_legal_review", "auctions_de"),
    )
    for flag_name, platform_key in toggle_platforms:
        if country_code and country_code != "AT" and platform_key.endswith("_at"):
            continue
        if country_code and country_code != "DE" and platform_key.endswith("_de"):
            continue
        if bool(payload.get(flag_name)) and platform_key not in normalized:
            normalized.append(platform_key)
    return tuple(normalized)


def _property_search_platforms_for_country(
    selected_platforms: tuple[str, ...],
    country_code: object,
    *,
    listing_mode: object | None = None,
    include_distressed_sale_signals: object = False,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[dict[str, object], ...]]:
    kept, removed_details = filter_selectable_property_platform_details(
        _normalize_property_search_platform_inputs(selected_platforms),
        country_code=normalize_country_code(resolve_country_code(country_code) or country_code),
        listing_mode=listing_mode,
        include_distressed_sale_signals=include_distressed_sale_signals,
    )
    return (
        kept,
        tuple(str(row.get("platform") or "").strip() for row in removed_details if str(row.get("platform") or "").strip()),
        removed_details,
    )


def _property_search_execution_platforms(
    selected_platforms: tuple[str, ...],
    preferences: dict[str, object] | None,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[dict[str, object], ...]]:
    payload = dict(preferences or {})
    country_code = normalize_country_code(resolve_country_code(payload.get("country_code")) or payload.get("country_code"))
    listing_mode = normalize_listing_mode(payload.get("listing_mode"))
    normalized_platforms = _normalize_property_search_platform_inputs(selected_platforms)
    if not normalized_platforms:
        normalized_platforms = _normalize_property_search_platform_inputs(payload.get("selected_platforms"))
    if not normalized_platforms:
        normalized_platforms = selectable_property_platform_keys(
            country_code=country_code,
            listing_mode=listing_mode,
            include_distressed_sale_signals=payload.get("include_distressed_sale_signals"),
        )
    elif "all" in normalized_platforms:
        normalized_platforms = selectable_property_platform_keys(
            country_code=country_code,
            listing_mode=listing_mode,
            include_distressed_sale_signals=payload.get("include_distressed_sale_signals"),
        )
    normalized_platforms = _property_search_platforms_with_family_toggles(
        normalized_platforms,
        payload,
    )
    normalized_platforms, removed_platforms, removed_platform_details = _property_search_platforms_for_country(
        normalized_platforms,
        country_code,
        listing_mode=listing_mode,
        include_distressed_sale_signals=payload.get("include_distressed_sale_signals"),
    )
    if normalized_platforms:
        return normalized_platforms, removed_platforms, removed_platform_details
    fallback_platforms = _property_search_platforms_with_family_toggles(
        tuple(
            default_platforms_for_country_listing_mode(
                country_code,
                listing_mode,
                property_type=payload.get("property_type"),
            )
        ),
        payload,
    )
    normalized_platforms, fallback_removed, fallback_removed_details = _property_search_platforms_for_country(
        fallback_platforms,
        country_code,
        listing_mode=listing_mode,
        include_distressed_sale_signals=payload.get("include_distressed_sale_signals"),
    )
    removed_platforms = tuple(dict.fromkeys((*removed_platforms, *fallback_removed)))
    detail_by_platform: dict[str, dict[str, object]] = {}
    for row in (*removed_platform_details, *fallback_removed_details):
        platform_key = str(dict(row).get("platform") or "").strip()
        if platform_key and platform_key not in detail_by_platform:
            detail_by_platform[platform_key] = dict(row)
    return normalized_platforms, removed_platforms, tuple(detail_by_platform.values())


def _property_search_single_country_for_platforms(selected_platforms: tuple[str, ...]) -> str:
    countries: set[str] = set()
    for platform in _normalize_property_search_platform_inputs(selected_platforms):
        if platform == "all":
            continue
        provider = property_provider_for_platform(platform)
        provider_country = normalize_country_code(getattr(provider, "country_code", "") or "")
        if provider_country:
            countries.add(provider_country)
    return next(iter(countries)) if len(countries) == 1 else ""


def _property_search_broaden_suggestions(
    *,
    request_preferences: dict[str, object],
    payload: dict[str, object],
) -> list[dict[str, object]]:
    suggestions: list[dict[str, object]] = []

    def _positive_int(value: object, default: int = 0) -> int:
        try:
            return max(0, int(float(str(value or "").strip())))
        except Exception:
            return default

    listing_total = _positive_int(payload.get("listing_total"), 0)
    if listing_total > 0:
        return []
    sources = [dict(row) for row in list(payload.get("sources") or []) if isinstance(row, dict)]
    outside_total = sum(_positive_int(row.get("location_mismatch_candidate_total"), 0) for row in sources)
    area_total = _positive_int(payload.get("filtered_area_total"), 0)
    floorplan_total = _positive_int(payload.get("filtered_floorplan_total"), 0)
    raw_total = sum(_positive_int(row.get("raw_listing_total"), 0) for row in sources)
    country_code = normalize_country_code(resolve_country_code(request_preferences.get("country_code")) or request_preferences.get("country_code"))
    region_code = str(request_preferences.get("region_code") or "").strip().lower()
    location_query = str(request_preferences.get("location_query") or "").strip()
    keywords = str(request_preferences.get("keywords") or "").strip()

    if outside_total > 0 and country_code == "CR" and location_query:
        location_values = [value.strip() for value in location_query.split(",") if value.strip()]
        if "monteverde" in location_query.lower() and not any(value.lower() == "santa elena" for value in location_values):
            suggestions.append(
                {
                    "title": "Broaden Monteverde to Santa Elena",
                    "detail": f"{outside_total} provider result(s) were outside the exact Monteverde match. Add Santa Elena for a controlled discovery pass before going country-wide.",
                    "tag": "Area",
                    "action_label": "Add Santa Elena",
                    "adjustments": {"region_code": "puntarenas", "location_query": "Monteverde, Santa Elena"},
                }
            )
        elif region_code not in {"puntarenas"}:
            suggestions.append(
                {
                    "title": "Move the search into Puntarenas",
                    "detail": f"{outside_total} provider result(s) were outside the current target. Puntarenas is the broader province for this Costa Rica search.",
                    "tag": "Area",
                    "action_label": "Use Puntarenas",
                    "adjustments": {"region_code": "puntarenas"},
                }
            )
        suggestions.append(
            {
                "title": "Try Puntarenas once",
                "detail": "Keep Costa Rica selected, but use the broader Puntarenas province once to discover nearby towns the providers actually index.",
                "tag": "Area",
                "action_label": "Use Puntarenas discovery",
                "adjustments": {"region_code": "puntarenas", "location_query": "Puntarenas"},
            }
        )

    min_area = _positive_int(request_preferences.get("min_area_m2"), 0)
    if area_total > 0 and min_area > 0:
        relaxed_area = max(0, min(min_area - 10, int(round(min_area * 0.65))))
        suggestions.append(
            {
                "title": f"Relax minimum area to {relaxed_area} m2",
                "detail": f"{area_total} home(s) were held back by the area filter. Use this only as a discovery pass, then restore the stricter size rule.",
                "tag": "Size",
                "action_label": f"Use {relaxed_area} m2",
                "adjustments": {"min_area_m2": relaxed_area},
            }
        )

    if keywords and raw_total > 0:
        suggestions.append(
            {
                "title": "Remove keyword post-filtering once",
                "detail": "Listing sites had inventory, but keyword filtering can be brittle in Costa Rica. Clear keywords for one discovery search.",
                "tag": "Keywords",
                "action_label": "Clear keywords",
                "adjustments": {"keywords": ""},
            }
        )

    if bool(request_preferences.get("require_floorplan")) and floorplan_total > 0:
        suggestions.append(
            {
                "title": "Try one discovery pass without a required floorplan",
                "detail": "Keep these homes visible while floorplan details are recovered in the background.",
                "tag": "Floorplan",
                "action_label": "Try discovery pass",
                "adjustments": {"require_floorplan": False},
            }
        )

    failed_sources = [str(row.get("source_label") or row.get("platform") or "").strip() for row in sources if str(row.get("error") or "").strip()]
    if failed_sources:
        suggestions.append(
            {
                "title": "Refresh unavailable sites",
                "detail": f"{len(failed_sources)} site{' needs' if len(failed_sources) == 1 else 's need'} another check before this market read is complete.",
                "tag": "Sites",
                "action_label": "Refresh sites",
                "adjustments": {},
            }
        )

    deduped: list[dict[str, object]] = []
    seen: set[str] = set()
    for suggestion in suggestions:
        title = str(suggestion.get("title") or "").strip().lower()
        if not title or title in seen:
            continue
        seen.add(title)
        deduped.append(suggestion)
    return deduped[:5]


def _property_search_pref_value_missing(value: object) -> bool:
    if value is None:
        return True
    if isinstance(value, str):
        return not value.strip()
    if isinstance(value, (list, tuple, set, dict)):
        return len(value) == 0
    return False


def _property_search_match_score_cap(preferences: dict[str, object] | None) -> int:
    try:
        snapshot = property_commercial_snapshot(preferences)
        return max(1, min(100, int(snapshot.get("max_match_score") or 35)))
    except Exception:
        return 35


def _property_search_mode(preferences: dict[str, object] | None) -> str:
    normalized = str(dict(preferences or {}).get("search_mode") or "").strip().lower()
    return normalized if normalized in {"strict", "discovery"} else "strict"


