def _property_search_budget_limit(preferences: dict[str, object] | None) -> float | None:
    payload = dict(preferences or {})
    for key in (
        "max_price_eur",
        "max_total_price_eur",
        "max_purchase_price_eur",
        "max_total_rent_eur",
        "max_monthly_rent_eur",
        "max_rent_eur",
    ):
        value = _float_or_none(payload.get(key))
        if isinstance(value, float) and value > 0.0:
            return value
    return None


def _property_search_candidate_price_for_budget(
    candidate: dict[str, object],
    *,
    listing_mode: object,
) -> float | None:
    facts = _property_candidate_display_facts(candidate)
    normalized_listing_mode = normalize_listing_mode(listing_mode)
    key_groups = (
        (
            "total_rent_eur",
            "rent_eur",
            "monthly_rent_eur",
            "warm_rent_eur",
            "cold_rent_eur",
            "price_eur",
        )
        if normalized_listing_mode == "rent"
        else (
            "purchase_price_eur",
            "buy_price_eur",
            "price_eur",
            "reserve_price_eur",
            "valuation_eur",
        )
    )
    for key in key_groups:
        value = _float_or_none(candidate.get(key))
        if not isinstance(value, float):
            value = _float_or_none(facts.get(key))
        if isinstance(value, float) and value > 0.0:
            return value
    return None


def _property_search_budget_block_is_reopenable(candidate: dict[str, object]) -> bool:
    reason_values = [
        candidate.get("hard_filter_reason"),
        candidate.get("filter_reason"),
        candidate.get("blocked_reason"),
        candidate.get("suppression_reason"),
    ]
    facts = _property_candidate_display_facts(candidate)
    for key in ("hard_filter_reason", "filter_reason", "blocked_reason", "suppression_reason"):
        reason_values.append(facts.get(key))
    normalized_reasons = [
        str(value or "").strip().lower()
        for value in reason_values
        if str(value or "").strip()
    ]
    if not normalized_reasons:
        return True
    budget_tokens = {"budget", "price", "rent", "cost", "afford"}
    hard_scope_tokens = {
        "area",
        "district",
        "location",
        "scope",
        "property_type",
        "type",
        "floorplan",
        "availability",
        "listing_mode",
        "transaction",
        "generic",
        "overview",
    }
    for reason in normalized_reasons:
        has_budget_token = any(token in reason for token in budget_tokens)
        has_other_hard_token = any(token in reason for token in hard_scope_tokens)
        if has_other_hard_token and not has_budget_token:
            return False
    return any(any(token in reason for token in budget_tokens) for reason in normalized_reasons)


def _property_search_area_hint_keys(preferences: dict[str, object] | None) -> set[str]:
    keys: set[str] = set()
    for hint in _property_search_location_hints(preferences):
        text = str(hint or "").strip().casefold()
        if not text:
            continue
        text = re.sub(r"\bwien\b", "vienna", text)
        for code in re.findall(r"\b\d{4,5}\b", text):
            keys.add(f"postal:{code}")
        normalized = re.sub(r"[^a-z0-9äöüß]+", "", text)
        if normalized:
            keys.add(f"text:{normalized}")
    return keys


def _property_search_area_change_is_expansion(
    *,
    run_preferences: dict[str, object] | None,
    current_preferences: dict[str, object] | None,
    changed_keys: list[str],
) -> bool:
    if (
        not changed_keys
        or not any(key in _PROPERTY_SEARCH_AREA_KEYS for key in changed_keys)
        or any(
            key not in _PROPERTY_SEARCH_AREA_KEYS
            and key not in _PROPERTY_SEARCH_REVALIDATION_NEUTRAL_KEYS
            for key in changed_keys
        )
    ):
        return False

    run_hints = _property_search_location_hints(run_preferences)
    current_hints = _property_search_location_hints(current_preferences)
    run_keys = _property_search_area_hint_keys(run_preferences)
    current_keys = _property_search_area_hint_keys(current_preferences)
    run_radius_m = _property_search_effective_adjacent_area_radius_m(
        preferences=run_preferences,
        location_hints=run_hints,
    )
    current_radius_m = _property_search_effective_adjacent_area_radius_m(
        preferences=current_preferences,
        location_hints=current_hints,
    )
    run_full_region = _property_truthy_flag(dict(run_preferences or {}).get("full_region_scope"))
    current_full_region = _property_truthy_flag(dict(current_preferences or {}).get("full_region_scope"))

    if run_keys and current_keys and run_keys.issubset(current_keys):
        return current_keys != run_keys or current_radius_m > run_radius_m
    if run_keys and current_full_region and not run_full_region and current_hints:
        return True
    return bool(run_keys and current_keys and current_radius_m > run_radius_m and run_keys == current_keys)


def _property_search_candidate_has_concrete_location(candidate: dict[str, object]) -> bool:
    facts = _property_candidate_display_facts(candidate)
    title = str(candidate.get("title") or candidate.get("listing_title") or "").strip()
    summary = str(candidate.get("summary") or candidate.get("fit_summary") or "").strip()
    if _property_listing_observed_postal_codes(title=title, summary=summary, property_facts=facts):
        return True
    if _property_candidate_point(facts) is not None:
        return True
    broad_location_values = {
        "austria",
        "at",
        "osterreich",
        "österreich",
        "vienna",
        "wien",
        "costa rica",
        "costarica",
        "germany",
        "deutschland",
    }
    for key in ("district", "postal_name", "location", "address", "street_address", "exact_address", "city"):
        value = str(facts.get(key) or "").strip()
        if not value or _property_location_value_is_source_scope_placeholder(value, facts):
            continue
        normalized = re.sub(r"[^a-z0-9äöüß]+", " ", value.casefold()).strip()
        compact = normalized.replace(" ", "")
        if normalized in broad_location_values or compact in broad_location_values:
            continue
        if re.search(r"\b\d{4,5}\b", value):
            return True
        if key in {"address", "street_address", "exact_address"} and len(normalized) >= 6:
            return True
        if key in {"district", "postal_name", "location", "city"} and len(normalized) >= 3:
            return True
    return False


def _property_search_area_block_is_reopenable(candidate: dict[str, object]) -> bool:
    reason_values = [
        candidate.get("hard_filter_reason"),
        candidate.get("filter_reason"),
        candidate.get("blocked_reason"),
        candidate.get("suppression_reason"),
    ]
    facts = _property_candidate_display_facts(candidate)
    for key in ("hard_filter_reason", "filter_reason", "blocked_reason", "suppression_reason"):
        reason_values.append(facts.get(key))
    normalized_reasons = [
        str(value or "").strip().lower()
        for value in reason_values
        if str(value or "").strip()
    ]
    if not normalized_reasons:
        return False
    area_tokens = {
        "area",
        "district",
        "location",
        "outside_selected_area",
        "postal",
        "region",
        "scope",
    }
    other_hard_tokens = {
        "afford",
        "availability",
        "budget",
        "cost",
        "floorplan",
        "generic",
        "listing_mode",
        "overview",
        "price",
        "property_type",
        "rent",
        "transaction",
        "type",
    }
    area_reason_seen = False
    for reason in normalized_reasons:
        has_area_token = any(token in reason for token in area_tokens)
        has_other_hard_token = any(token in reason for token in other_hard_tokens)
        if has_other_hard_token and not has_area_token:
            return False
        if has_area_token:
            area_reason_seen = True
    return area_reason_seen


def _property_search_available_within_years(preferences: dict[str, object] | None) -> int:
    try:
        return max(0, min(10, int(float(str(dict(preferences or {}).get("available_within_years") or "").strip()))))
    except Exception:
        return 0


def _property_search_effective_hard_rule_policy(preferences: dict[str, object] | None) -> dict[str, object]:
    request_preferences, execution_policy = _property_search_execution_preferences(dict(preferences or {}))
    relaxed_filters = {
        str(item or "").strip()
        for item in list(execution_policy.get("discovery_relaxed_filters") or [])
        if str(item or "").strip()
    }
    min_area_m2 = _float_or_none(request_preferences.get("min_area_m2")) or 0.0
    available_within_years = _property_search_available_within_years(request_preferences)
    return {
        "available_within_years": 0 if "available_within_years" in relaxed_filters else available_within_years,
        "enforce_floorplan_filter": bool(execution_policy.get("enforce_floorplan_filter")),
        "min_area_m2": 0.0 if "min_area_m2" in relaxed_filters else max(0.0, float(min_area_m2 or 0.0)),
        "property_type": [] if "property_type" in relaxed_filters else list(normalize_property_type_values(request_preferences.get("property_type"))),
        "require_barrier_free": _property_truthy_flag(request_preferences.get("require_barrier_free")),
        "relaxed_filters": relaxed_filters,
    }


def _property_search_property_type_relaxed(
    *,
    run_property_type: object,
    current_property_type: object,
) -> bool:
    run_types = [str(item or "").strip().lower() for item in list(normalize_property_type_values(run_property_type) or []) if str(item or "").strip()]
    current_types = [str(item or "").strip().lower() for item in list(normalize_property_type_values(current_property_type) or []) if str(item or "").strip()]
    if not run_types or run_types == ["any"]:
        return False
    if not current_types:
        return True
    if current_types == ["any"]:
        any_types = {"apartment", "house", "land"}
        return all(item in any_types for item in run_types)
    return set(run_types).issubset(set(current_types)) and set(current_types) != set(run_types)


def _property_search_relaxed_filter_keys(
    *,
    run_preferences: dict[str, object] | None,
    current_preferences: dict[str, object] | None,
    changed_keys: list[str],
) -> set[str]:
    allowed_keys = (
        _PROPERTY_SEARCH_BUDGET_KEYS
        | _PROPERTY_SEARCH_AREA_KEYS
        | _PROPERTY_SEARCH_HARD_RULE_KEYS
        | _PROPERTY_SEARCH_REVALIDATION_NEUTRAL_KEYS
    )
    if not changed_keys or any(key not in allowed_keys for key in changed_keys):
        return set()

    relaxed: set[str] = set()
    run_budget = _property_search_budget_limit(run_preferences)
    current_budget = _property_search_budget_limit(current_preferences)
    if isinstance(run_budget, float) and isinstance(current_budget, float) and current_budget > run_budget:
        relaxed.add("budget")

    if _property_search_area_change_is_expansion(
        run_preferences=run_preferences,
        current_preferences=current_preferences,
        changed_keys=changed_keys,
    ):
        relaxed.add("area")

    run_policy = _property_search_effective_hard_rule_policy(run_preferences)
    current_policy = _property_search_effective_hard_rule_policy(current_preferences)
    run_min_area = _float_or_none(run_policy.get("min_area_m2")) or 0.0
    current_min_area = _float_or_none(current_policy.get("min_area_m2")) or 0.0
    if run_min_area > 0.0 and current_min_area < run_min_area:
        relaxed.add("min_area_m2")

    if bool(run_policy.get("enforce_floorplan_filter")) and not bool(current_policy.get("enforce_floorplan_filter")):
        relaxed.add("require_floorplan")

    if bool(run_policy.get("require_barrier_free")) and not bool(current_policy.get("require_barrier_free")):
        relaxed.add("require_barrier_free")

    run_years = int(run_policy.get("available_within_years") or 0)
    current_years = int(current_policy.get("available_within_years") or 0)
    if run_years > 0 and (current_years == 0 or current_years > run_years):
        relaxed.add("available_within_years")

    if "property_type" in changed_keys or "search_mode" in changed_keys:
        if _property_search_property_type_relaxed(
            run_property_type=run_policy.get("property_type"),
            current_property_type=current_policy.get("property_type"),
        ):
            relaxed.add("property_type")

    return relaxed


def _property_search_candidate_filter_block_keys(candidate: dict[str, object]) -> tuple[set[str], bool]:
    reason_values = [
        candidate.get("hard_filter_reason"),
        candidate.get("filter_reason"),
        candidate.get("blocked_reason"),
        candidate.get("suppression_reason"),
        candidate.get("failed_filter_key"),
        candidate.get("filter_key"),
    ]
    facts = _property_candidate_display_facts(candidate)
    for key in (
        "hard_filter_reason",
        "filter_reason",
        "blocked_reason",
        "suppression_reason",
        "failed_filter_key",
        "filter_key",
    ):
        reason_values.append(facts.get(key))
    normalized_reasons = [
        str(value or "").strip().lower()
        for value in reason_values
        if str(value or "").strip()
    ]
    if not normalized_reasons:
        return set(), True

    block_keys: set[str] = set()
    unsafe = False
    for reason in normalized_reasons:
        compact = re.sub(r"[^a-z0-9]+", "_", reason).strip("_")
        plain = reason.replace("_", " ")
        if compact in {
            "max_price_eur",
            "max_rent_eur",
            "max_monthly_rent_eur",
            "max_total_rent_eur",
            "price_above_budget",
            "rent_above_budget",
            "budget",
        } or "above budget" in plain or "price above" in plain or "rent above" in plain:
            block_keys.add("budget")
        if compact in {"min_area_m2", "minimum_area", "below_min_area", "too_small"} or (
            ("below" in plain or "minimum" in plain or "too small" in plain)
            and ("area" in plain or "m2" in plain or "sqm" in plain)
        ):
            block_keys.add("min_area_m2")
        if compact in {"require_floorplan", "floorplan", "floorplan_required"} or "floor plan" in plain or "layout verification" in plain:
            block_keys.add("require_floorplan")
        if compact in {"require_barrier_free", "barrier_free", "accessibility"} or "barrier" in plain or "wheelchair" in plain:
            block_keys.add("require_barrier_free")
        if compact in {"available_within_years", "availability_mismatch"} or "move-in" in plain or "move in" in plain or "availability" in plain:
            block_keys.add("available_within_years")
        if compact in {
            "property_type",
            "property_type_mismatch",
            "wrong_property_type",
            "type_mismatch",
        } or "property type" in plain or "non-residential" in plain:
            block_keys.add("property_type")
        if compact in {"outside_selected_area", "area_mismatch", "location_mismatch", "location_scope"}:
            block_keys.add("area")

        unsafe_markers = {
            "false_positive",
            "generic_listing_page",
            "listing_mode_mismatch",
            "not_a_listing",
            "overview",
            "property_location_conflicts_with_active_search",
            "property_missing_concrete_location",
            "source_scope",
            "transaction_mismatch",
            "wrong_listing_mode",
        }
        if compact in unsafe_markers:
            unsafe = True
        if any(marker in plain for marker in ("wrong listing mode", "not a listing", "generic listing", "false positive")):
            unsafe = True
    return block_keys, unsafe


def _property_search_candidate_matches_current_hard_rules(
    candidate: dict[str, object],
    *,
    current_preferences: dict[str, object] | None,
) -> bool:
    facts = _property_candidate_display_facts(candidate)
    property_url = str(
        candidate.get("property_url")
        or candidate.get("listing_url")
        or candidate.get("review_url")
        or ""
    ).strip()
    title = str(candidate.get("title") or candidate.get("listing_title") or "").strip()
    summary = str(candidate.get("summary") or candidate.get("fit_summary") or "").strip()
    preferences = dict(current_preferences or {})
    current_country = normalize_country_code(preferences.get("country_code"))
    candidate_country = normalize_country_code(facts.get("country_code"))
    if current_country and candidate_country and candidate_country != current_country:
        return False
    if _property_candidate_is_generic_listing_page(
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=facts,
    ):
        return False
    location_hints = _property_search_location_hints(preferences)
    if location_hints and not _property_candidate_matches_search_area(
        location_hints=location_hints,
        request_preferences=preferences,
        source_spec={
            "country_code": preferences.get("country_code"),
            "region_code": preferences.get("region_code"),
        },
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=facts,
    ):
        return False
    listing_mode = normalize_listing_mode(preferences.get("listing_mode"))
    if _property_candidate_listing_mode_mismatch(
        listing_mode=listing_mode,
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=facts,
    ):
        return False

    current_policy = _property_search_effective_hard_rule_policy(preferences)
    if not _property_candidate_matches_requested_property_type(
        property_type=current_policy.get("property_type"),
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=facts,
    ):
        return False
    if not _property_candidate_matches_min_area(
        min_area_m2=float(current_policy.get("min_area_m2") or 0.0),
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=facts,
    ):
        return False
    if not _property_candidate_matches_availability_horizon(
        available_within_years=int(current_policy.get("available_within_years") or 0),
        property_facts=facts,
    ):
        return False
    if bool(current_policy.get("enforce_floorplan_filter")) and not _property_candidate_has_floorplan(
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=facts,
    ):
        return False
    if bool(current_policy.get("require_barrier_free")) and not _property_candidate_is_barrier_free(facts):
        return False
    return True


def _property_search_snapshot_candidate_rows(snapshot: dict[str, object]) -> list[dict[str, object]]:
    summary = dict(snapshot.get("summary") or {}) if isinstance(snapshot.get("summary"), dict) else {}
    rows: list[dict[str, object]] = []
    for key in (
        "ranked_candidates",
        "top_candidates",
        "research_candidates",
        "filtered_candidates",
        "held_back_candidates",
        "candidates",
    ):
        rows.extend(dict(row) for row in list(summary.get(key) or []) if isinstance(row, dict))
    for source in list(summary.get("sources") or []):
        if not isinstance(source, dict):
            continue
        source_label = str(source.get("source_label") or source.get("label") or source.get("platform") or "").strip()
        for key in (
            "top_candidates",
            "research_candidates",
            "filtered_candidates",
            "held_back_candidates",
            "candidates",
        ):
            for raw_row in list(source.get(key) or []):
                if not isinstance(raw_row, dict):
                    continue
                row = dict(raw_row)
                if source_label and not str(row.get("source_label") or "").strip():
                    row["source_label"] = source_label
                rows.append(row)
    return rows


def _property_search_candidate_identity(candidate: dict[str, object]) -> str:
    facts = _property_candidate_display_facts(candidate)
    for value in (
        candidate.get("candidate_ref"),
        candidate.get("research_candidate_ref"),
        candidate.get("source_ref"),
        candidate.get("property_url"),
        candidate.get("review_url"),
        candidate.get("listing_id"),
        facts.get("listing_url"),
    ):
        normalized = urllib.parse.urldefrag(str(value or "").strip())[0]
        if normalized:
            return normalized.lower()
    return "|".join(
        part
        for part in (
            str(candidate.get("title") or "").strip().lower(),
            str(facts.get("postal_name") or facts.get("address") or "").strip().lower(),
        )
        if part
    )


def _property_search_revalidate_area_expansion_snapshot(
    snapshot: dict[str, object],
    *,
    current_preferences: dict[str, object] | None,
) -> dict[str, object]:
    if not isinstance(snapshot, dict) or not snapshot:
        return snapshot
    run_preferences = _property_search_run_preferences_payload(snapshot)
    if not run_preferences:
        return snapshot
    changed_keys = _property_search_brief_changed_keys(
        run_preferences=run_preferences,
        current_preferences=current_preferences,
    )
    if not _property_search_area_change_is_expansion(
        run_preferences=run_preferences,
        current_preferences=current_preferences,
        changed_keys=changed_keys,
    ):
        return snapshot

    run_hints = _property_search_location_hints(run_preferences)
    current_hints = _property_search_location_hints(current_preferences)
    if not current_hints:
        return snapshot
    candidate_rows = _property_search_snapshot_candidate_rows(snapshot)
    if not candidate_rows:
        return snapshot

    current_source_spec = {
        "country_code": dict(current_preferences or {}).get("country_code"),
        "region_code": dict(current_preferences or {}).get("region_code"),
    }
    run_source_spec = {
        "country_code": dict(run_preferences or {}).get("country_code"),
        "region_code": dict(run_preferences or {}).get("region_code"),
    }
    reopened_rows: list[dict[str, object]] = []
    seen: set[str] = set()
    for raw_candidate in candidate_rows:
        candidate = dict(raw_candidate)
        facts = _property_candidate_display_facts(candidate)
        if not _property_search_area_block_is_reopenable(candidate):
            continue
        if not _property_search_candidate_has_concrete_location(candidate):
            continue
        property_url = str(
            candidate.get("property_url")
            or candidate.get("listing_url")
            or candidate.get("review_url")
            or ""
        ).strip()
        title = str(candidate.get("title") or candidate.get("listing_title") or "").strip()
        summary_text = str(candidate.get("summary") or candidate.get("fit_summary") or "").strip()
        if _property_candidate_matches_search_area(
            location_hints=run_hints,
            request_preferences=run_preferences,
            source_spec=run_source_spec,
            property_url=property_url,
            title=title,
            summary=summary_text,
            property_facts=facts,
        ):
            continue
        if not _property_candidate_matches_search_area(
            location_hints=current_hints,
            request_preferences=current_preferences,
            source_spec=current_source_spec,
            property_url=property_url,
            title=title,
            summary=summary_text,
            property_facts=facts,
        ):
            continue
        identity = _property_search_candidate_identity(candidate)
        if identity and identity in seen:
            continue
        if identity:
            seen.add(identity)
        cleaned = dict(candidate)
        for key in (
            "status",
            "review_status",
            "candidate_status",
            "filter_status",
            "hard_filter_reason",
            "filter_reason",
            "blocked_reason",
            "suppression_reason",
            "filtered_out",
            "hard_filtered",
        ):
            cleaned.pop(key, None)
        cleaned["area_revalidated"] = True
        cleaned["revalidated_from_old_brief"] = True
        cleaned["area_revalidated_current_hints"] = list(current_hints)
        cleaned.setdefault(
            "fit_score",
            cleaned.get("ranking_score") or cleaned.get("assessment_fit_score") or 1.0,
        )
        reopened_rows.append(cleaned)
    if not reopened_rows:
        return snapshot

    ranked_candidates = _property_search_ranked_candidates_from_sources(
        [{"source_label": "Saved candidates", "top_candidates": reopened_rows}],
        limit=None,
    )
    if not ranked_candidates:
        return snapshot

    summary = dict(snapshot.get("summary") or {}) if isinstance(snapshot.get("summary"), dict) else {}

    def _safe_int(*values: object) -> int:
        for value in values:
            try:
                return max(0, int(float(str(value or "").strip())))
            except Exception:
                continue
        return 0

    previous_ranked_total = _safe_int(summary.get("ranked_total"), summary.get("ranked_candidate_total"))
    previous_filtered_total = _safe_int(summary.get("filtered_total"), summary.get("held_back_total"))
    message = (
        "Saved candidates were rechecked with the current area. "
        "Start a fresh search when you want new site coverage too."
    )
    summary.update(
        {
            "ranked_candidates": ranked_candidates,
            "ranked_total": len(ranked_candidates),
            "ranked_candidate_total": len(ranked_candidates),
            "listing_total": max(_safe_int(summary.get("listing_total")), len(ranked_candidates)),
            "filtered_total": 0,
            "held_back_total": 0,
            "score_demoted_total": 0,
            "filtered_low_fit_total": 0,
            "brief_preferences_revalidated": True,
            "brief_snapshot_status": "revalidated_saved_candidates",
            "brief_revalidated_reason": "area_expanded",
            "brief_revalidated_message": message,
            "brief_revalidated_changed_keys": changed_keys[:20],
            "previous_ranked_total": previous_ranked_total,
            "previous_filtered_total": previous_filtered_total,
            "revalidated_ranked_total": len(ranked_candidates),
            "can_refresh_with_current_brief": True,
        }
    )
    return {
        **dict(snapshot),
        "summary": summary,
        "property_search_preferences": dict(current_preferences or {}),
        "message": message,
        "brief_preferences_stale": False,
        "stale_run_snapshot": False,
        "brief_preferences_revalidated": True,
    }


def _property_search_revalidate_relaxed_hard_rules_snapshot(
    snapshot: dict[str, object],
    *,
    current_preferences: dict[str, object] | None,
) -> dict[str, object]:
    if not isinstance(snapshot, dict) or not snapshot:
        return snapshot
    run_preferences = _property_search_run_preferences_payload(snapshot)
    if not run_preferences:
        return snapshot
    changed_keys = _property_search_brief_changed_keys(
        run_preferences=run_preferences,
        current_preferences=current_preferences,
    )
    relaxed_filter_keys = _property_search_relaxed_filter_keys(
        run_preferences=run_preferences,
        current_preferences=current_preferences,
        changed_keys=changed_keys,
    )
    if not relaxed_filter_keys:
        return snapshot

    candidate_rows = _property_search_snapshot_candidate_rows(snapshot)
    if not candidate_rows:
        return snapshot
    reopened_rows: list[dict[str, object]] = []
    seen: set[str] = set()
    for raw_candidate in candidate_rows:
        candidate = dict(raw_candidate)
        block_keys, unsafe_block = _property_search_candidate_filter_block_keys(candidate)
        if unsafe_block or not block_keys or not block_keys.issubset(relaxed_filter_keys):
            continue
        if not _property_search_candidate_matches_current_hard_rules(
            candidate,
            current_preferences=current_preferences,
        ):
            continue
        identity = _property_search_candidate_identity(candidate)
        if identity and identity in seen:
            continue
        if identity:
            seen.add(identity)
        cleaned = dict(candidate)
        for key in (
            "status",
            "review_status",
            "candidate_status",
            "filter_status",
            "hard_filter_reason",
            "filter_reason",
            "blocked_reason",
            "suppression_reason",
            "failed_filter_key",
            "filter_key",
            "filtered_out",
            "hard_filtered",
        ):
            cleaned.pop(key, None)
        cleaned["hard_rules_revalidated"] = True
        cleaned["revalidated_from_old_brief"] = True
        cleaned["hard_rules_revalidated_filters"] = sorted(block_keys)
        cleaned.setdefault("fit_score", cleaned.get("ranking_score") or cleaned.get("assessment_fit_score") or 1.0)
        reopened_rows.append(cleaned)
    if not reopened_rows:
        return snapshot

    ranked_candidates = _property_search_ranked_candidates_from_sources(
        [{"source_label": "Saved candidates", "top_candidates": reopened_rows}],
        limit=None,
    )
    if not ranked_candidates:
        return snapshot
    summary = dict(snapshot.get("summary") or {}) if isinstance(snapshot.get("summary"), dict) else {}

    def _safe_int(*values: object) -> int:
        for value in values:
            try:
                return max(0, int(float(str(value or "").strip())))
            except Exception:
                continue
        return 0

    previous_ranked_total = _safe_int(summary.get("ranked_total"), summary.get("ranked_candidate_total"))
    previous_filtered_total = _safe_int(summary.get("filtered_total"), summary.get("held_back_total"))
    message = (
        "Saved candidates were rechecked with the current rules. "
        "Start a fresh search when you want new site coverage too."
    )
    summary.update(
        {
            "ranked_candidates": ranked_candidates,
            "ranked_total": len(ranked_candidates),
            "ranked_candidate_total": len(ranked_candidates),
            "listing_total": max(_safe_int(summary.get("listing_total")), len(ranked_candidates)),
            "filtered_total": 0,
            "held_back_total": 0,
            "score_demoted_total": 0,
            "filtered_low_fit_total": 0,
            "brief_preferences_revalidated": True,
            "brief_snapshot_status": "revalidated_saved_candidates",
            "brief_revalidated_reason": "hard_rules_relaxed",
            "brief_revalidated_message": message,
            "brief_revalidated_changed_keys": changed_keys[:20],
            "brief_revalidated_filters": sorted(relaxed_filter_keys),
            "previous_ranked_total": previous_ranked_total,
            "previous_filtered_total": previous_filtered_total,
            "revalidated_ranked_total": len(ranked_candidates),
            "can_refresh_with_current_brief": True,
        }
    )
    return {
        **dict(snapshot),
        "summary": summary,
        "property_search_preferences": dict(current_preferences or {}),
        "message": message,
        "brief_preferences_stale": False,
        "stale_run_snapshot": False,
        "brief_preferences_revalidated": True,
    }


def _property_search_revalidate_budget_expansion_snapshot(
    snapshot: dict[str, object],
    *,
    current_preferences: dict[str, object] | None,
) -> dict[str, object]:
    if not isinstance(snapshot, dict) or not snapshot:
        return snapshot
    run_preferences = _property_search_run_preferences_payload(snapshot)
    if not run_preferences:
        return snapshot
    changed_keys = _property_search_brief_changed_keys(
        run_preferences=run_preferences,
        current_preferences=current_preferences,
    )
    if (
        not changed_keys
        or not any(key in _PROPERTY_SEARCH_BUDGET_KEYS for key in changed_keys)
        or any(key not in _PROPERTY_SEARCH_BUDGET_KEYS and key not in _PROPERTY_SEARCH_REVALIDATION_NEUTRAL_KEYS for key in changed_keys)
    ):
        return snapshot
    run_budget = _property_search_budget_limit(run_preferences)
    current_budget = _property_search_budget_limit(current_preferences)
    if not isinstance(run_budget, float) or not isinstance(current_budget, float) or current_budget <= run_budget:
        return snapshot
    listing_mode = dict(current_preferences or {}).get("listing_mode") or run_preferences.get("listing_mode")
    candidate_rows = _property_search_snapshot_candidate_rows(snapshot)
    if not candidate_rows:
        return snapshot
    reopened_rows: list[dict[str, object]] = []
    seen: set[str] = set()
    for raw_candidate in candidate_rows:
        candidate = dict(raw_candidate)
        price = _property_search_candidate_price_for_budget(candidate, listing_mode=listing_mode)
        if not isinstance(price, float) or price <= run_budget or price > current_budget:
            continue
        if not _property_search_budget_block_is_reopenable(candidate):
            continue
        identity = _property_search_candidate_identity(candidate)
        if identity and identity in seen:
            continue
        if identity:
            seen.add(identity)
        cleaned = dict(candidate)
        for key in (
            "status",
            "review_status",
            "candidate_status",
            "filter_status",
            "hard_filter_reason",
            "filter_reason",
            "blocked_reason",
            "suppression_reason",
            "filtered_out",
            "hard_filtered",
        ):
            cleaned.pop(key, None)
        cleaned["budget_revalidated"] = True
        cleaned["revalidated_from_old_brief"] = True
        cleaned["budget_revalidated_price_eur"] = round(price, 2)
        cleaned["budget_revalidated_previous_limit_eur"] = round(run_budget, 2)
        cleaned["budget_revalidated_current_limit_eur"] = round(current_budget, 2)
        cleaned.setdefault("fit_score", cleaned.get("ranking_score") or cleaned.get("assessment_fit_score") or 1.0)
        reopened_rows.append(cleaned)
    if not reopened_rows:
        return snapshot
    ranked_candidates = _property_search_ranked_candidates_from_sources(
        [{"source_label": "Saved candidates", "top_candidates": reopened_rows}],
        limit=None,
    )
    if not ranked_candidates:
        return snapshot
    summary = dict(snapshot.get("summary") or {}) if isinstance(snapshot.get("summary"), dict) else {}
    previous_ranked_total = max(
        0,
        int(float(str(summary.get("ranked_total") or summary.get("ranked_candidate_total") or 0))),
    )
    previous_filtered_total = max(
        0,
        int(float(str(summary.get("filtered_total") or summary.get("held_back_total") or 0))),
    )
    message = (
        "Saved candidates were rechecked with the current budget. "
        "Start a fresh search when you want new site coverage too."
    )
    summary.update(
        {
            "ranked_candidates": ranked_candidates,
            "ranked_total": len(ranked_candidates),
            "ranked_candidate_total": len(ranked_candidates),
            "listing_total": max(int(summary.get("listing_total") or 0), len(ranked_candidates)),
            "filtered_total": 0,
            "held_back_total": 0,
            "score_demoted_total": 0,
            "filtered_low_fit_total": 0,
            "brief_preferences_revalidated": True,
            "brief_snapshot_status": "revalidated_saved_candidates",
            "brief_revalidated_reason": "budget_expanded",
            "brief_revalidated_message": message,
            "brief_revalidated_changed_keys": changed_keys[:20],
            "previous_ranked_total": previous_ranked_total,
            "previous_filtered_total": previous_filtered_total,
            "revalidated_ranked_total": len(ranked_candidates),
            "can_refresh_with_current_brief": True,
        }
    )
    return {
        **dict(snapshot),
        "summary": summary,
        "property_search_preferences": dict(current_preferences or {}),
        "message": message,
        "brief_preferences_stale": False,
        "stale_run_snapshot": False,
        "brief_preferences_revalidated": True,
    }


def _property_search_resolve_max_results_per_source(
    preferences: dict[str, object] | None,
    requested_value: object,
) -> int | None:
    try:
        snapshot = property_commercial_snapshot(preferences)
        plan_key = normalize_property_plan_key(snapshot.get("current_plan_key") or "free")
        plan_result_cap = int(snapshot.get("max_results_per_source") or 0)
        try:
            requested_cap = int(float(str(requested_value).strip()))
        except Exception:
            requested_cap = 0
        if requested_cap <= 0:
            return None
        if property_plan_has_unlimited_provider_results(plan_key, plan_result_cap):
            return max(1, requested_cap)
        return max(1, min(plan_result_cap or requested_cap, requested_cap))
    except Exception:
        return None


def _property_search_defined_max_results_value(
    preferences: dict[str, object] | None,
    summary: dict[str, object] | None,
) -> object:
    preference_payload = dict(preferences or {})
    if "max_results_per_source" in preference_payload:
        return preference_payload.get("max_results_per_source")
    summary_payload = dict(summary or {})
    if "max_results_per_source" in summary_payload:
        return summary_payload.get("max_results_per_source")
    return None


def _property_candidate_effective_fit_score(*, assessment_fit_score: object, ranked_fit_score: object) -> float:
    try:
        assessment_value = max(0.0, float(assessment_fit_score or 0.0))
    except Exception:
        assessment_value = 0.0
    try:
        ranked_value = max(0.0, float(ranked_fit_score or 0.0))
    except Exception:
        ranked_value = 0.0
    return max(assessment_value, ranked_value)


def _property_search_execution_preferences(preferences: dict[str, object] | None) -> tuple[dict[str, object], dict[str, object]]:
    request_preferences = dict(preferences or {})
    search_mode = _property_search_mode(request_preferences)
    require_floorplan = _property_truthy_flag(request_preferences.get("require_floorplan"))
    enforce_floorplan_filter = _property_search_floorplan_hard_filter_enabled(request_preferences)
    raw_property_type = normalize_property_type_values(request_preferences.get("property_type"))
    if isinstance(raw_property_type, tuple):
        raw_property_type = list(raw_property_type)
    requested_property_types = [str(item).strip().lower() for item in list(raw_property_type or []) if str(item).strip()]
    requested_property_type_is_any = bool(requested_property_types and requested_property_types != ["any"])
    discovery_min_area_m2 = _float_or_none(request_preferences.get("min_area_m2")) or 0.0
    discovery_availability_years = 0
    try:
        discovery_availability_years = max(0, int(float(str(request_preferences.get("available_within_years") or "0").strip())))
    except Exception:
        discovery_availability_years = 0
    discovery_relaxed_filters: list[str] = []
    if search_mode == "discovery" and enforce_floorplan_filter:
        enforce_floorplan_filter = False
        discovery_relaxed_filters.append("require_floorplan")
    if search_mode == "discovery" and requested_property_type_is_any:
        discovery_relaxed_filters.append("property_type")
    if search_mode == "discovery" and discovery_min_area_m2 > 0.0:
        discovery_relaxed_filters.append("min_area_m2")
    if search_mode == "discovery" and discovery_availability_years > 0:
        discovery_relaxed_filters.append("available_within_years")
    request_preferences["search_mode"] = search_mode
    request_preferences["require_floorplan"] = require_floorplan
    request_preferences["floorplan_requirement_mode"] = "hard" if enforce_floorplan_filter else ("soft" if require_floorplan else "off")
    request_preferences["discovery_relaxed_filters"] = list(discovery_relaxed_filters)
    return request_preferences, {
        "search_mode": search_mode,
        "require_floorplan": require_floorplan,
        "enforce_floorplan_filter": enforce_floorplan_filter,
        "discovery_relaxed_filters": list(discovery_relaxed_filters),
    }


def _property_discovery_soft_distance_penalty(*, requested_limit_m: float, actual_m: float | None) -> float:
    requested = max(1.0, float(requested_limit_m or 0.0))
    if not isinstance(actual_m, float) or actual_m <= 0.0:
        return 4.0
    ratio = max(1.0, float(actual_m) / requested)
    overshoot = max(0.0, float(actual_m) - requested)
    return round(min(16.0, max(3.0, (ratio - 1.0) * 8.0, overshoot / 300.0)), 1)


def _property_search_run_expired(at_iso: str, *, ttl_seconds: int = _PROPERTY_SEARCH_RUN_TTL_SECONDS) -> bool:
    return _state_property_search_run_expired(at_iso, ttl_seconds=ttl_seconds, parse_utcish=_parse_utcish)


def _property_search_run_retention_seconds() -> int:
    return _property_search_storage._property_search_run_retention_seconds()  # type: ignore[attr-defined]


def _property_search_run_stale_seconds() -> int:
    return _state_property_search_run_stale_seconds(default_seconds=_PROPERTY_SEARCH_RUN_STALE_DEFAULT_SECONDS)


def _property_search_replacement_run_stale_seconds() -> int:
    raw_value = str(os.getenv("EA_PROPERTY_SEARCH_REPLACEMENT_RUN_STALE_SECONDS") or "").strip()
    if not raw_value:
        return 120
    try:
        parsed = int(raw_value)
    except Exception:
        return 120
    return max(30, min(parsed, _property_search_run_stale_seconds()))


def _property_search_active_run_stale_seconds() -> int:
    raw_value = str(os.getenv("EA_PROPERTY_SEARCH_ACTIVE_RUN_STALE_SECONDS") or "").strip()
    if not raw_value:
        return _property_search_replacement_run_stale_seconds()
    try:
        parsed = int(raw_value)
    except Exception:
        return _property_search_replacement_run_stale_seconds()
    return max(30, min(parsed, _property_search_run_stale_seconds()))


def _property_search_review_open_timeout_seconds() -> float:
    return _state_property_search_review_open_timeout_seconds(default_seconds=20.0)


def _property_search_inline_review_packet_limit() -> int:
    raw_value = str(
        os.getenv("PROPERTYQUARRY_SEARCH_INLINE_REVIEW_PACKET_LIMIT")
        or os.getenv("EA_PROPERTY_SEARCH_INLINE_REVIEW_PACKET_LIMIT")
        or ""
    ).strip()
    if not raw_value:
        return 3
    try:
        parsed = int(float(raw_value))
    except Exception:
        return 3
    return max(0, min(parsed, 50))


def _property_search_should_prepare_inline_review_packet(*, row_index: int, inline_limit: int) -> bool:
    try:
        normalized_index = int(row_index)
    except Exception:
        return False
    try:
        normalized_limit = int(inline_limit)
    except Exception:
        normalized_limit = 0
    return normalized_index > 0 and normalized_limit > 0 and normalized_index <= normalized_limit


def _property_search_run_is_stale(state: dict[str, object]) -> bool:
    liveness_state = dict(state)
    event_times: list[datetime] = []
    for event in list(liveness_state.get("events") or []):
        if not isinstance(event, dict):
            continue
        event_step = str(event.get("step") or "").strip().lower()
        if event_step in {"", "queued", "starting", "recovery_pickup_started"}:
            continue
        parsed_event_at = _parse_utcish(str(event.get("at") or ""))
        if parsed_event_at is not None:
            event_times.append(parsed_event_at)
    latest_event_at = max(event_times) if event_times else None
    row_updated_at = _parse_utcish(str(liveness_state.get("updated_at") or ""))
    if latest_event_at is not None:
        liveness_state["updated_at"] = latest_event_at.isoformat()
    return _state_property_search_run_is_stale(
        liveness_state,
        terminal_statuses=_PROPERTY_SEARCH_TERMINAL_STATUSES,
        parse_utcish=_parse_utcish,
        stale_seconds=_property_search_run_stale_seconds(),
    )


def _property_search_replacement_run_is_stale(state: dict[str, object]) -> bool:
    liveness_state = dict(state)
    return _state_property_search_run_is_stale(
        liveness_state,
        terminal_statuses=_PROPERTY_SEARCH_TERMINAL_STATUSES,
        parse_utcish=_parse_utcish,
        stale_seconds=_property_search_replacement_run_stale_seconds(),
    )


def _property_search_sources_resolved_pickup_can_resume(state: dict[str, object]) -> bool:
    payload = dict(state or {})
    summary = dict(payload.get("summary") or {}) if isinstance(payload.get("summary"), dict) else {}
    current_step = str(payload.get("current_step") or summary.get("current_step") or "").strip().lower()
    if current_step != "sources_resolved":
        return False
    pickup_status = str(summary.get("execution_pickup_status") or payload.get("execution_pickup_status") or "").strip().lower()
    try:
        pickup_attempt = max(0, int(float(str(summary.get("execution_pickup_attempt") or payload.get("execution_pickup_attempt") or 0).strip())))
    except Exception:
        pickup_attempt = 0
    return pickup_status == "started" or pickup_attempt > 0


