def _property_candidate_text(
    *,
    property_url: str,
    title: str = "",
    summary: str = "",
    property_facts: dict[str, object] | None = None,
) -> str:
    facts = dict(property_facts or {})
    fact_values: list[str] = []
    for value in facts.values():
        if isinstance(value, (str, int, float)):
            fact_values.append(str(value))
        elif isinstance(value, (list, tuple)):
            fact_values.extend(str(item) for item in value if isinstance(item, (str, int, float)))
    return " ".join(
        part
        for part in (
            str(property_url or ""),
            str(title or ""),
            str(summary or ""),
            *fact_values,
        )
        if str(part or "").strip()
    ).strip().lower()


def _property_candidate_has_floorplan(
    *,
    property_url: str,
    title: str = "",
    summary: str = "",
    property_facts: dict[str, object] | None = None,
    preview: dict[str, object] | None = None,
) -> bool:
    facts = dict(property_facts or {})
    preview_payload = dict(preview or {})
    if _property_facts_have_floorplan(facts, preview=preview_payload):
        return True
    preview_facts = (
        dict(preview_payload.get("property_facts_json") or {})
        if isinstance(preview_payload.get("property_facts_json"), dict)
        else {}
    )
    if preview_facts and _property_facts_have_floorplan(preview_facts, preview=preview_payload):
        return True
    diagnostic_fact_keys = {
        "blocking_constraints_json",
        "floorplan_research_status",
        "floorplan_recovery_diagnostics",
        "floorplan_requirement_mode",
        "mismatch_reasons_json",
        "missing_fact_research",
        "missing_facts_json",
        "missing_floorplan_diagnostics",
        "provider_recovery_diagnostics",
        "research_tasks",
        "unknowns_json",
    }
    text_facts = {}
    for key, value in {**preview_facts, **facts}.items():
        normalized_key = str(key or "").strip().lower()
        if (
            not normalized_key
            or normalized_key in diagnostic_fact_keys
            or normalized_key.endswith("_diagnostics")
            or normalized_key.endswith("_research_status")
        ):
            continue
        text_facts[key] = value
    text = " ".join(
        part
        for part in (
            _property_candidate_text(
                property_url=property_url,
                title=title,
                summary=summary,
                property_facts=text_facts,
            ),
            str(preview_payload.get("title") or "").lower(),
            str(preview_payload.get("summary") or "").lower(),
            str(preview_payload.get("listing_id") or "").lower(),
        )
        if str(part or "").strip()
    )
    negative_markers = (
        "no floorplan",
        "no floor plan",
        "no extracted floorplan",
        "without floorplan",
        "without a floor plan",
        "without clear floorplan",
        "kein grundriss",
        "keinen grundriss",
        "ohne grundriss",
    )
    if any(marker in text for marker in negative_markers):
        return False
    compact_text_value = re.sub(r"[^a-z0-9äöüß]+", "", text)
    markers = (
        "grundriss",
        "floor plan",
        "floorplan",
        "floor-plan",
        "lageplan",
        "raumskizze",
        "plan_top",
        "plantop",
        "layout plan",
    )
    return any(marker in text or marker.replace(" ", "").replace("-", "") in compact_text_value for marker in markers)


def _property_candidate_matches_requested_property_type(
    *,
    property_type: object,
    property_url: str,
    title: str = "",
    summary: str = "",
    property_facts: dict[str, object] | None = None,
) -> bool:
    requested_types = [item for item in normalize_property_type_values(property_type) if item]
    if not requested_types:
        return True
    if requested_types == ["any"]:
        requested_types = ["apartment", "house", "land"]

    facts = dict(property_facts or {})
    fact_types = normalize_property_type_values(
        facts.get("property_type")
        or facts.get("object_type")
        or facts.get("category")
        or facts.get("listing_type")
    )
    concrete_types = {"apartment", "house", "office", "land"}

    concrete_requested_types = [item for item in requested_types if item in concrete_types]
    concrete_fact_types = [item for item in fact_types if item in concrete_types]
    if concrete_requested_types and concrete_fact_types and any(item in concrete_fact_types for item in concrete_requested_types):
        return True

    text = _property_candidate_text(
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=facts,
    )
    direct_text = " ".join(
        part.lower()
        for part in (
            str(property_url or "").strip(),
            str(title or "").strip(),
            str(summary or "").strip(),
        )
        if str(part or "").strip()
    )
    direct_compact_text_value = re.sub(r"[^a-z0-9äöüß]+", "", direct_text)
    compact_text_value = re.sub(r"[^a-z0-9äöüß]+", "", text)
    def _has_text_marker(markers: tuple[str, ...], include_compact: bool = False) -> bool:
        if include_compact:
            return any(
                marker in text or marker.replace(" ", "") in compact_text_value or marker.replace("-", "") in compact_text_value
                for marker in markers
            )
        return any(marker in text for marker in markers)

    has_office_marker = _has_text_marker(_PROPERTY_OFFICE_TEXT_MARKERS, include_compact=True)
    has_non_residential_only_marker = any(
        marker in text or marker.replace(" ", "") in compact_text_value
        for marker in _PROPERTY_NON_RESIDENTIAL_ONLY_MARKERS
    )
    has_direct_apartment_marker = any(marker in direct_text for marker in _PROPERTY_APARTMENT_TEXT_MARKERS)
    has_direct_house_marker = any(marker in direct_text for marker in _PROPERTY_HOUSE_TEXT_MARKERS)
    has_direct_land_marker = any(
        marker in direct_text
        or marker.replace(" ", "") in direct_compact_text_value
        or marker.replace("-", "") in direct_compact_text_value
        for marker in _PROPERTY_LAND_TEXT_MARKERS
    )
    has_direct_residential_text_signal = has_direct_apartment_marker or has_direct_house_marker or has_direct_land_marker

    has_apartment_marker = _has_text_marker(_PROPERTY_APARTMENT_TEXT_MARKERS)
    has_house_marker = _has_text_marker(_PROPERTY_HOUSE_TEXT_MARKERS)
    has_land_marker = _has_text_marker(_PROPERTY_LAND_TEXT_MARKERS, include_compact=True)

    def _single_requested_type_match(requested_type: str) -> bool:
        if requested_type == "any":
            return True
        if requested_type == "office":
            return has_office_marker
        if requested_type == "land":
            return has_land_marker and not (has_apartment_marker or has_house_marker)
        if requested_type == "apartment":
            if has_non_residential_only_marker and not has_direct_residential_text_signal:
                return False
            if has_office_marker and not (has_apartment_marker or has_house_marker or has_land_marker):
                return False
            if has_house_marker and not has_apartment_marker:
                return False
            if has_land_marker and not (has_apartment_marker or has_house_marker):
                return False
            return True
        if requested_type == "house":
            if has_non_residential_only_marker and not has_direct_residential_text_signal:
                return False
            if has_office_marker and not (has_house_marker or has_apartment_marker or has_land_marker):
                return False
            if has_apartment_marker and not has_house_marker:
                return False
            if has_land_marker and not (has_apartment_marker or has_house_marker):
                return False
            return True
        return True

    return any(_single_requested_type_match(item) for item in requested_types)


def _property_candidate_area_sqm(
    *,
    property_url: str,
    title: str = "",
    summary: str = "",
    property_facts: dict[str, object] | None = None,
) -> float | None:
    facts = dict(property_facts or {})
    for key in (
        "area_sqm",
        "area_m2",
        "living_area_m2",
        "living_area_sqm",
        "usable_area_m2",
        "usable_area_sqm",
        "wohnflaeche_sqm",
        "wohnfläche_sqm",
    ):
        area = _float_or_none(facts.get(key))
        if isinstance(area, float) and area > 0.0:
            return area
    text = _property_candidate_text(
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=facts,
    )
    return _property_extract_area_value(text)


def _property_candidate_matches_min_area(
    *,
    min_area_m2: float,
    property_url: str,
    title: str = "",
    summary: str = "",
    property_facts: dict[str, object] | None = None,
) -> bool:
    if min_area_m2 <= 0.0:
        return True
    area = _property_candidate_area_sqm(
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=property_facts,
    )
    return isinstance(area, float) and area >= min_area_m2


def _property_candidate_min_area_status(
    *,
    min_area_m2: float,
    property_url: str,
    title: str = "",
    summary: str = "",
    property_facts: dict[str, object] | None = None,
) -> str:
    if min_area_m2 <= 0.0:
        return "pass"
    area = _property_candidate_area_sqm(
        property_url=property_url,
        title=title,
        summary=summary,
        property_facts=property_facts,
    )
    if not isinstance(area, float):
        return "unknown"
    return "pass" if area >= min_area_m2 else "fail"


_PROPERTY_MONTH_NAME_INDEX = {
    "jan": 1,
    "january": 1,
    "januar": 1,
    "feb": 2,
    "february": 2,
    "februar": 2,
    "mar": 3,
    "march": 3,
    "maerz": 3,
    "apr": 4,
    "april": 4,
    "may": 5,
    "mai": 5,
    "jun": 6,
    "june": 6,
    "juni": 6,
    "jul": 7,
    "july": 7,
    "juli": 7,
    "aug": 8,
    "august": 8,
    "sep": 9,
    "sept": 9,
    "september": 9,
    "oct": 10,
    "okt": 10,
    "october": 10,
    "oktober": 10,
    "nov": 11,
    "november": 11,
    "dec": 12,
    "dez": 12,
    "december": 12,
    "dezember": 12,
}
_PROPERTY_IMMEDIATE_AVAILABILITY_MARKERS = (
    "ab sofort",
    "sofort",
    "immediately",
    "ready now",
    "available now",
    "bezugsfertig",
)


def _property_parse_availability_date(value: object) -> datetime | None:
    text = compact_text(str(value or "").strip(), fallback="", limit=120)
    if not text:
        return None
    lowered = text.lower()
    if any(marker in lowered for marker in _PROPERTY_IMMEDIATE_AVAILABILITY_MARKERS):
        return datetime.now(timezone.utc)
    normalized = lowered.replace(".", " ").replace(",", " ").replace("/", " ").replace("-", " ")
    normalized = " ".join(normalized.split())
    iso_match = re.search(r"(20\d{2})-(\d{2})-(\d{2})", text)
    if iso_match:
        try:
            return datetime(
                int(iso_match.group(1)),
                int(iso_match.group(2)),
                int(iso_match.group(3)),
                tzinfo=timezone.utc,
            )
        except Exception:
            return None
    quarter_match = re.search(r"\bq([1-4])\s*(20\d{2})\b", normalized)
    if quarter_match:
        quarter = int(quarter_match.group(1))
        year = int(quarter_match.group(2))
        return datetime(year, quarter * 3, 28, tzinfo=timezone.utc)
    quarter_match = re.search(r"\b(20\d{2})\s*q([1-4])\b", normalized)
    if quarter_match:
        year = int(quarter_match.group(1))
        quarter = int(quarter_match.group(2))
        return datetime(year, quarter * 3, 28, tzinfo=timezone.utc)
    month_match = re.search(r"\b([a-zA-Z]+)\s+(20\d{2})\b", normalized)
    if month_match:
        month = _PROPERTY_MONTH_NAME_INDEX.get(month_match.group(1).lower())
        if month:
            return datetime(int(month_match.group(2)), month, 28, tzinfo=timezone.utc)
    year_match = re.search(r"\b(20\d{2})\b", normalized)
    if year_match:
        return datetime(int(year_match.group(1)), 12, 31, tzinfo=timezone.utc)
    return None


def _property_candidate_availability_date(
    *,
    property_facts: dict[str, object] | None = None,
) -> datetime | None:
    facts = dict(property_facts or {})
    for key in ("available_from_iso", "available_from", "availability_date", "move_in_date", "move_in", "availability_label"):
        parsed = _property_parse_availability_date(facts.get(key))
        if parsed is not None:
            return parsed
    return None


def _property_candidate_matches_availability_horizon(
    *,
    available_within_years: int,
    property_facts: dict[str, object] | None = None,
) -> bool:
    if available_within_years <= 0:
        return True
    available_at = _property_candidate_availability_date(property_facts=property_facts)
    if available_at is None:
        return True
    deadline = datetime.now(timezone.utc) + timedelta(days=366 * available_within_years)
    return available_at <= deadline


def _property_distance_within_relaxed_radius(
    *,
    actual_m: object,
    requested_limit_m: int,
    relaxation_factor: float = 3.0,
) -> tuple[bool, str, float]:
    if requested_limit_m <= 0:
        return True, "not_requested", 0.0
    try:
        actual = float(actual_m or 0.0)
    except Exception:
        actual = 0.0
    if actual <= 0.0:
        return True, "unknown", actual
    if actual <= float(requested_limit_m):
        return True, "strict", actual
    relaxed_limit = float(requested_limit_m) * max(1.0, float(relaxation_factor or 1.0))
    if actual <= relaxed_limit:
        return True, "relaxed", actual
    return False, "outside_relaxed", actual


def _property_distance_relaxation_factor(value: object) -> float:
    normalized = str(value or "").strip().lower()
    if normalized in {"hard", "must_have", "must-have", "strict"}:
        return 1.0
    if normalized in {"important", "high", "strong", "strong_wish", "strong-wish", "strong wish"}:
        return 3.0
    if normalized in {"nice_to_have", "nice-to-have", "soft", "low"}:
        return 5.0
    return 3.0


def _property_distance_is_avoid_mode(value: object) -> bool:
    normalized = str(value or "").strip().lower()
    return normalized in {"avoid", "avoid_nearby", "avoid-nearby", "avoid_in_vicinity", "avoid-vicinity"}


def _property_distance_is_hard_mode(value: object) -> bool:
    normalized = str(value or "").strip().lower()
    return normalized in {"hard", "must_have", "must-have", "strict"}


def _property_distance_is_strong_mode(value: object) -> bool:
    normalized = str(value or "").strip().lower()
    return normalized in {"important", "high", "strong", "strong_wish", "strong-wish", "strong wish"}


def _property_distance_is_nice_mode(value: object) -> bool:
    normalized = str(value or "").strip().lower()
    return normalized in {"nice_to_have", "nice-to-have", "soft", "low"}


def _property_append_distance_relaxation(
    facts: dict[str, object],
    *,
    label: str,
    requested_m: int,
    actual_m: float,
) -> None:
    existing = facts.get("distance_relaxations_json")
    rows = list(existing) if isinstance(existing, list) else []
    rows.append({"label": label, "requested_m": int(requested_m), "actual_m": int(actual_m)})
    facts["distance_relaxations_json"] = rows


def _property_append_distance_unknown(
    facts: dict[str, object],
    *,
    label: str,
    requested_m: int,
) -> None:
    existing = facts.get("distance_unknowns_json")
    rows = list(existing) if isinstance(existing, list) else []
    row = {"label": label, "requested_m": int(requested_m)}
    if row not in rows:
        rows.append(row)
    facts["distance_unknowns_json"] = rows


def _property_append_distance_avoidance(
    facts: dict[str, object],
    *,
    label: str,
    requested_m: int,
    actual_m: float,
) -> None:
    existing = facts.get("distance_avoidances_json")
    rows = list(existing) if isinstance(existing, list) else []
    row = {"label": label, "requested_m": int(requested_m), "actual_m": int(actual_m)}
    if row not in rows:
        rows.append(row)
    facts["distance_avoidances_json"] = rows


def _property_soft_distance_score_curve(
    *,
    actual_m: float,
    requested_limit_m: int,
    positive_cap: float,
    negative_cap: float,
) -> tuple[float, str]:
    if requested_limit_m <= 0 or actual_m <= 0.0:
        return 0.0, "unknown"
    requested = float(requested_limit_m)
    if actual_m <= requested:
        return max(0.0, float(positive_cap) * max(0.0, 1.0 - (actual_m / requested))), (
            "boost" if actual_m <= requested * 0.5 else "within_target"
        )
    outer_limit = requested * 2.0
    if actual_m >= outer_limit:
        return -max(0.0, float(negative_cap)), "full_malus"
    ratio = max(0.0, min(1.0, (actual_m - requested) / requested))
    return -max(0.0, float(negative_cap)) * ratio, "soft_malus"


def _property_apply_distance_gate(
    facts: dict[str, object],
    *,
    request_preferences: dict[str, object],
    preference_key: str,
    fact_key: str,
    label: str,
    fact_is_resolved: bool | None = None,
) -> bool:
    limit_m = int(request_preferences.get(preference_key) or 0)
    if limit_m <= 0:
        return True
    importance_key = (
        f"{preference_key[:-2]}_importance"
        if preference_key.endswith("_m")
        else f"{preference_key}_importance"
    )
    importance_mode = request_preferences.get(importance_key)
    actual_value = facts.get(fact_key) if fact_is_resolved is not False else None
    if _property_distance_is_avoid_mode(importance_mode):
        try:
            actual = float(actual_value or 0.0)
        except Exception:
            actual = 0.0
        if actual <= 0.0:
            _property_append_distance_unknown(facts, label=label, requested_m=limit_m)
            return True
        if actual <= float(limit_m):
            _property_append_distance_avoidance(facts, label=label, requested_m=limit_m, actual_m=actual)
        return True
    distance_ok, distance_mode, actual_m = _property_distance_within_relaxed_radius(
        actual_m=actual_value,
        requested_limit_m=limit_m,
        relaxation_factor=_property_distance_relaxation_factor(importance_mode),
    )
    if distance_mode == "unknown":
        _property_append_distance_unknown(facts, label=label, requested_m=limit_m)
        return True
    elif distance_mode == "relaxed":
        _property_append_distance_relaxation(facts, label=label, requested_m=limit_m, actual_m=actual_m)
    if _property_distance_is_hard_mode(importance_mode):
        return distance_ok
    return True


def _property_search_distance_preference_rows(
) -> tuple[tuple[str, tuple[str, ...], str], ...]:
    """Project the canonical fact registry into search gate/scoring rows."""
    rows: list[tuple[str, tuple[str, ...], str]] = []
    for spec in property_fact_distance_specs(search_supported_only=True):
        preference_key = next(
            (
                str(value).strip()
                for value in list(spec.get("required_preference_keys") or [])
                if str(value).strip().startswith("max_distance_to_")
            ),
            "",
        )
        fact_keys = tuple(
            str(value).strip()
            for value in list(spec.get("aliases") or [])
            if str(value).strip()
        )
        if not preference_key or not fact_keys:
            continue
        rows.append(
            (
                preference_key,
                fact_keys,
                str(spec.get("search_label") or spec.get("label") or fact_keys[0]).strip(),
            )
        )
    return tuple(rows)


def _property_search_canonical_distance_preferences(
    preferences: Mapping[str, object] | None,
) -> dict[str, object]:
    """Collapse legacy distance aliases before gate and score evaluation."""
    payload = dict(preferences or {})
    alias_pairs = (
        ("max_distance_to_subway_m", "max_distance_to_underground_m"),
        (
            "max_distance_to_subway_importance",
            "max_distance_to_underground_importance",
        ),
    )
    for canonical_key, legacy_key in alias_pairs:
        if payload.get(canonical_key) in (None, "", 0, 0.0, False) and payload.get(
            legacy_key
        ) not in (None, "", 0, 0.0, False):
            payload[canonical_key] = payload.get(legacy_key)
    return payload


def _property_search_requires_fresh_distance_facts(
    preferences: Mapping[str, object] | None,
) -> bool:
    """Return whether search-time scoring needs a full-fidelity preview.

    Public preview cache rows intentionally omit exact coordinates and all
    paired distance evidence.  A must-have, strong-wish, or avoid preference
    therefore has to bypass that cache before the candidate is gated/scored.
    """
    normalized_preferences = _property_search_canonical_distance_preferences(
        preferences
    )
    return any(
        str(row.get("priority") or "lazy").strip().lower() == "required"
        for row in property_fact_requirement_plan(
            facts={},
            preferences=normalized_preferences,
            include_resolved=True,
        )
    )


def _property_candidate_passes_resolved_distance_gates(
    *,
    facts: dict[str, object],
    preferences: Mapping[str, object] | None,
    plan: Iterable[Mapping[str, object]],
) -> bool:
    """Apply hard gates only to facts verified by the canonical plan."""
    normalized_preferences = _property_search_canonical_distance_preferences(
        preferences
    )
    plan_by_key = {
        str(row.get("key") or "").strip(): dict(row)
        for row in plan
        if str(row.get("key") or "").strip()
    }
    for preference_key, fact_keys, label in _property_search_distance_preference_rows():
        canonical_fact_key = str(fact_keys[0])
        plan_row = plan_by_key.get(canonical_fact_key) or {}
        resolved = (
            str(plan_row.get("state") or "unknown").strip().lower()
            == "resolved"
        )
        source_key = (
            str(plan_row.get("source_key") or canonical_fact_key).strip()
            if resolved
            else canonical_fact_key
        )
        if not _property_apply_distance_gate(
            facts,
            request_preferences=normalized_preferences,
            preference_key=preference_key,
            fact_key=source_key,
            label=label,
            fact_is_resolved=resolved,
        ):
            return False
    return True


def _property_distance_preference_score_adjustment(
    *,
    preferences: dict[str, object] | None,
    property_facts: dict[str, object] | None,
    property_url: object = "",
) -> tuple[float, tuple[str, ...]]:
    payload = _property_search_canonical_distance_preferences(preferences)
    facts = property_facts if isinstance(property_facts, dict) else {}
    plan_by_key = {
        str(row.get("key") or "").strip(): dict(row)
        for row in property_fact_requirement_plan(
            facts=facts,
            preferences=payload,
            include_resolved=True,
            property_url=property_url,
        )
    }
    adjustment = 0.0
    notes: list[str] = []
    for preference_key, fact_keys, label in _property_search_distance_preference_rows():
        try:
            limit_m = int(payload.get(preference_key) or 0)
        except Exception:
            limit_m = 0
        if limit_m <= 0:
            continue
        importance_key = (
            f"{preference_key[:-2]}_importance"
            if preference_key.endswith("_m")
            else f"{preference_key}_importance"
        )
        importance_mode = str(payload.get(importance_key) or "").strip().lower()
        if importance_mode in {"", "any", "neutral", "no_preference", "no-preference"}:
            continue
        plan_row = plan_by_key.get(str(fact_keys[0])) or {}
        fact_value = (
            plan_row.get("value")
            if str(plan_row.get("state") or "unknown").strip().lower()
            == "resolved"
            else None
        )
        observed_fact_key = (
            str(plan_row.get("source_key") or fact_keys[0]).strip()
            if fact_value not in (None, "", 0, 0.0)
            else ""
        )

        def _distance_preference_note(*, keep_farther_than: bool = False) -> str:
            observed = _float_or_none(fact_value)
            if not isinstance(observed, float) or observed <= 0:
                return ""
            place_name = ""
            if observed_fact_key:
                place_name = compact_text(
                    str(facts.get(f"{observed_fact_key.removesuffix('_m')}_name") or "").strip(),
                    fallback="",
                    limit=80,
                )
            subject = f"Nearest {label}"
            if place_name:
                subject = f"{subject}: {place_name}"
            if keep_farther_than and limit_m > 0:
                return f"{subject} is {int(observed)} m away; you asked to keep it farther than {int(limit_m)} m."
            if limit_m > 0:
                return f"{subject} is {int(observed)} m away; your limit was {int(limit_m)} m."
            return f"{subject} is {int(observed)} m away."

        if _property_distance_is_avoid_mode(importance_mode):
            try:
                actual_m = float(fact_value or 0.0)
            except Exception:
                actual_m = 0.0
            if actual_m <= 0.0:
                _property_append_distance_unknown(facts, label=label, requested_m=limit_m)
            elif actual_m <= float(limit_m):
                adjustment -= 6.0
                notes.append(_distance_preference_note(keep_farther_than=True) or f"{label} too close for avoid preference")
            else:
                adjustment += 1.0
                notes.append(f"{label} avoided")
            continue
        distance_ok, distance_mode, _actual_m = _property_distance_within_relaxed_radius(
            actual_m=fact_value,
            requested_limit_m=limit_m,
            relaxation_factor=_property_distance_relaxation_factor(importance_mode),
        )
        if _property_distance_is_hard_mode(importance_mode):
            if distance_mode == "strict":
                adjustment += 2.0
                notes.append(f"{label} matched")
            elif distance_mode == "relaxed":
                adjustment += 0.5
                notes.append(f"{label} slightly farther than requested")
            elif distance_mode == "unknown":
                _property_append_distance_unknown(facts, label=label, requested_m=limit_m)
            continue
        if _property_distance_is_strong_mode(importance_mode):
            observed_m = _float_or_none(fact_value)
            if not isinstance(observed_m, float) or observed_m <= 0.0:
                _property_append_distance_unknown(facts, label=label, requested_m=limit_m)
                continue
            score_delta, score_mode = _property_soft_distance_score_curve(
                actual_m=observed_m,
                requested_limit_m=limit_m,
                positive_cap=6.0,
                negative_cap=6.0,
            )
            adjustment += score_delta
            if score_mode == "boost":
                notes.append(f"{label} close by")
            elif score_mode == "within_target":
                notes.append(f"{label} within requested radius")
            elif score_mode in {"soft_malus", "full_malus"}:
                notes.append(_distance_preference_note() or f"{label} farther away than wished")
            continue
        if _property_distance_is_nice_mode(importance_mode):
            observed_m = _float_or_none(fact_value)
            if not isinstance(observed_m, float) or observed_m <= 0.0:
                _property_append_distance_unknown(facts, label=label, requested_m=limit_m)
                continue
            score_delta, score_mode = _property_soft_distance_score_curve(
                actual_m=observed_m,
                requested_limit_m=limit_m,
                positive_cap=3.0,
                negative_cap=3.0,
            )
            adjustment += score_delta
            if score_mode in {"boost", "within_target"}:
                notes.append(f"{label} nearby")
            elif score_mode in {"soft_malus", "full_malus"}:
                notes.append(_distance_preference_note() or f"{label} less convenient")
    return adjustment, tuple(notes[:8])


_PROPERTY_SEARCH_SCORE_ALGORITHM_VERSION = "propertyquarry.search-score.v2"


def _property_search_score_context(
    *,
    candidate: Mapping[str, object],
    preferences: Mapping[str, object] | None,
    preview: Mapping[str, object] | None = None,
    ordinal: int | None = None,
    location_penalty_points: float | None = None,
    apply_unknowns_penalty: bool | None = None,
) -> dict[str, object]:
    """Capture immutable inputs needed to reproduce a search score later."""
    context = (
        dict(candidate.get("search_score_context") or {})
        if isinstance(candidate.get("search_score_context"), Mapping)
        else {}
    )
    property_url = urllib.parse.urldefrag(
        str(
            candidate.get("property_url")
            or candidate.get("listing_url")
            or context.get("property_url")
            or ""
        ).strip()
    )[0]
    preview_context = (
        dict(context.get("preview") or {})
        if isinstance(context.get("preview"), Mapping)
        else {}
    )
    supplied_preview = dict(preview or {})
    for key in (
        "title",
        "summary",
        "floorplan_urls_json",
        "floorplan_urls",
        "has_floorplan",
        "floorplan_count",
    ):
        value = supplied_preview.get(key)
        if value not in (None, "", (), [], {}):
            preview_context[key] = _property_fact_json_copy(value)
    preview_context.setdefault("title", str(candidate.get("title") or "").strip())
    preview_context.setdefault("summary", str(candidate.get("summary") or "").strip())
    resolved_ordinal = max(
        1,
        int(
            ordinal
            if ordinal is not None
            else context.get("ordinal") or candidate.get("ordinal") or 1
        ),
    )
    resolved_location_penalty = max(
        0.0,
        float(
            location_penalty_points
            if location_penalty_points is not None
            else context.get("location_penalty_points") or 0.0
        ),
    )
    normalized_preferences = dict(preferences or {})
    resolved_unknowns_penalty = (
        bool(apply_unknowns_penalty)
        if apply_unknowns_penalty is not None
        else bool(
            context.get("apply_unknowns_penalty")
            if "apply_unknowns_penalty" in context
            else _property_truthy_flag(
                normalized_preferences.get("apply_unknowns_penalty")
            )
        )
    )
    return {
        "algorithm_version": _PROPERTY_SEARCH_SCORE_ALGORITHM_VERSION,
        "property_url": property_url,
        "ordinal": resolved_ordinal,
        "location_penalty_points": round(resolved_location_penalty, 2),
        "apply_unknowns_penalty": resolved_unknowns_penalty,
        "preview": preview_context,
    }


def _property_search_score_candidate(
    *,
    candidate: Mapping[str, object],
    assessment: Mapping[str, object] | None,
    property_facts: dict[str, object],
    preferences: Mapping[str, object] | None,
    preview: Mapping[str, object] | None = None,
    ordinal: int | None = None,
    location_penalty_points: float | None = None,
    apply_unknowns_penalty: bool | None = None,
) -> dict[str, object]:
    """Apply the one deterministic search score composition used by every rerank."""
    recomputed_fact_keys = {
        "distance_preference_adjustment_points",
        "distance_preference_notes",
        "austria_preference_adjustment_points",
        "austria_preference_notes",
        "distance_unknowns_json",
        "distance_relaxations_json",
        "distance_avoidances_json",
    }
    digest_ignored_fact_keys = set(recomputed_fact_keys)
    score_input_facts = {
        str(key): _property_fact_json_copy(value)
        for key, value in property_facts.items()
        if str(key) not in digest_ignored_fact_keys
    }
    for derived_key in recomputed_fact_keys:
        property_facts.pop(derived_key, None)
    score_context = _property_search_score_context(
        candidate=candidate,
        preferences=preferences,
        preview=preview,
        ordinal=ordinal,
        location_penalty_points=location_penalty_points,
        apply_unknowns_penalty=apply_unknowns_penalty,
    )
    property_url = str(score_context.get("property_url") or "").strip()
    preview_context = dict(score_context.get("preview") or {})
    scoring_preview = {**preview_context, "property_facts_json": property_facts}
    resolved_ordinal = int(score_context.get("ordinal") or 1)
    resolved_location_penalty = float(
        score_context.get("location_penalty_points") or 0.0
    )
    normalized_preferences = dict(preferences or {})
    resolved_unknowns_penalty = bool(score_context.get("apply_unknowns_penalty"))
    normalized_assessment = dict(assessment or {})
    assessment_fit_score = max(
        0.0,
        float(normalized_assessment.get("fit_score") or 0.0),
    )
    base_rank_score = _property_scout_rank_score(
        property_url=property_url,
        assessment=normalized_assessment,
        preview=scoring_preview,
        ordinal=resolved_ordinal,
    )
    objective_review_boost = _property_scout_objective_review_boost(
        property_url=property_url,
        preview=scoring_preview,
    )
    source_order_review_decay = (
        min(
            objective_review_boost,
            max(0.0, float(resolved_ordinal - 1) * 3.0),
        )
        if abs(float(assessment_fit_score) - 50.0) <= 0.01
        else 0.0
    )
    ranked_fit_score = max(0.0, base_rank_score - resolved_location_penalty)
    unknowns_penalty_points = 0.0
    if resolved_unknowns_penalty:
        unknowns_penalty_points = _property_candidate_unknowns_penalty(
            assessment=normalized_assessment,
            property_facts=property_facts,
        )
        ranked_fit_score = max(0.0, ranked_fit_score - unknowns_penalty_points)
    distance_adjustment, distance_notes = _property_distance_preference_score_adjustment(
        preferences=normalized_preferences,
        property_facts=property_facts,
        property_url=property_url,
    )
    if distance_adjustment:
        ranked_fit_score = max(0.0, ranked_fit_score + float(distance_adjustment))
    if distance_notes:
        property_facts["distance_preference_adjustment_points"] = round(
            float(distance_adjustment),
            2,
        )
        property_facts["distance_preference_notes"] = list(distance_notes)
    austria_adjustment, austria_notes = _property_austria_preference_score_adjustment(
        preferences=normalized_preferences,
        property_facts=property_facts,
        title=str(scoring_preview.get("title") or "").strip(),
        summary=str(scoring_preview.get("summary") or "").strip(),
    )
    if austria_adjustment:
        ranked_fit_score = max(0.0, ranked_fit_score + float(austria_adjustment))
    if austria_notes:
        property_facts["austria_preference_adjustment_points"] = round(
            float(austria_adjustment),
            2,
        )
        property_facts["austria_preference_notes"] = list(austria_notes)
    discovery_penalty_points = max(
        0.0,
        float(property_facts.get("discovery_soft_penalty_points") or 0.0),
    )
    ranked_fit_score = max(0.0, ranked_fit_score - discovery_penalty_points)
    adjusted_fit_score = _property_candidate_effective_fit_score(
        assessment_fit_score=assessment_fit_score,
        ranked_fit_score=ranked_fit_score,
    )
    score_provenance = {
        "algorithm_version": _PROPERTY_SEARCH_SCORE_ALGORITHM_VERSION,
        "assessment_digest": property_fact_input_digest(normalized_assessment),
        "preference_digest": property_fact_input_digest(normalized_preferences),
        "facts_digest": property_fact_input_digest(score_input_facts),
        "components": {
            "base_rank_score": round(float(base_rank_score), 2),
            "objective_review_boost_points": round(
                float(objective_review_boost),
                2,
            ),
            "source_order_review_decay_points": round(
                float(source_order_review_decay),
                2,
            ),
            "location_penalty_points": round(resolved_location_penalty, 2),
            "unknowns_penalty_points": round(float(unknowns_penalty_points), 2),
            "distance_adjustment_points": round(float(distance_adjustment), 2),
            "austria_adjustment_points": round(float(austria_adjustment), 2),
            "discovery_penalty_points": round(discovery_penalty_points, 2),
        },
    }
    return {
        "fit_score": round(float(ranked_fit_score), 2),
        "assessment_fit_score": round(float(assessment_fit_score), 2),
        "adjusted_fit_score": round(float(adjusted_fit_score), 2),
        "property_facts": _property_fact_json_copy(property_facts),
        "search_score_context": score_context,
        "score_provenance": score_provenance,
    }


