def _is_willhaben_property_url(value: object) -> bool:
    from .outbound_url_security import canonical_http_hostname, hostname_matches_allowlist

    normalized = str(value or "").strip()
    if not normalized:
        return False
    host = canonical_http_hostname(normalized)
    return bool(host) and hostname_matches_allowlist(host, _WILLHABEN_HOST_MARKERS)


def _willhaben_packet_panorama_media_urls(packet: dict[str, object]) -> list[str]:
    explicit = set(
        _property_tour_safe_captured_urls(
            packet.get("panorama_media_urls_json"),
            limit=40,
        )
    )
    assets = packet.get("media_assets_json")
    if not isinstance(assets, list):
        return []
    urls: list[str] = []
    for entry in assets:
        if not isinstance(entry, dict):
            continue
        if not bool(entry.get("panorama_candidate")):
            continue
        reason = str(entry.get("panorama_reason") or "").strip().lower()
        if reason != "xmp_equirectangular":
            continue
        safe_urls = _property_tour_safe_captured_urls([entry.get("url")], limit=1)
        if not safe_urls:
            continue
        url = safe_urls[0]
        if explicit and url not in explicit:
            continue
        urls.append(url)
    return list(dict.fromkeys(urls))[:40]


def _willhaben_packet_source_virtual_tour_url(packet: dict[str, object]) -> str:
    raw_property_facts = packet.get("property_facts_json")
    property_facts = dict(raw_property_facts) if isinstance(raw_property_facts, dict) else {}
    attribute_map = dict(property_facts.get("attribute_map") or {}) if isinstance(property_facts.get("attribute_map"), dict) else {}
    attribute_candidates: list[str] = []
    value = attribute_map.get("VIRTUAL_VIEW_LINK/URL")
    if isinstance(value, list):
        attribute_candidates.extend(str(entry or "").strip() for entry in value if str(entry or "").strip())
    elif str(value or "").strip():
        attribute_candidates.append(str(value or "").strip())
    discovered_urls: list[str] = []
    for candidate in attribute_candidates:
        discovered_urls.extend(_extract_urls_from_text(candidate))
    for url in discovered_urls:
        normalized = _property_tour_safe_captured_360_url(url)
        if normalized:
            return normalized
    return _first_non_empty_text(
        _property_tour_safe_captured_360_url(packet.get("source_virtual_tour_url")),
        _property_tour_safe_captured_360_url(property_facts.get("source_virtual_tour_url")),
    )


def _willhaben_packet_panorama_source(packet: dict[str, object]) -> str:
    raw_property_facts = packet.get("property_facts_json")
    property_facts = dict(raw_property_facts) if isinstance(raw_property_facts, dict) else {}
    return _first_non_empty_text(
        packet.get("panorama_source"),
        property_facts.get("panorama_source"),
    )


def _ensure_hosted_property_tour_url(structured_output: dict[str, object]) -> dict[str, object]:
    normalized = dict(structured_output or {})
    if _first_non_empty_text(normalized.get("hosted_url")):
        return normalized
    existing_hosted_url = _existing_hosted_property_tour_url(normalized)
    if existing_hosted_url:
        vendor_public_url = _first_non_empty_text(
            normalized.get("crezlo_public_url"),
            normalized.get("public_url"),
            normalized.get("share_url"),
        )
        normalized["hosted_url"] = existing_hosted_url
        normalized["public_url"] = existing_hosted_url
        if vendor_public_url:
            normalized["crezlo_public_url"] = vendor_public_url
        return normalized
    try:
        from app.services.tool_execution_browseract_adapter import BrowserActToolAdapter

        hosted_url = str(
            BrowserActToolAdapter._publish_crezlo_public_tour_bundle({"structured_output_json": normalized})  # type: ignore[attr-defined]
            or ""
        ).strip()
    except Exception:
        hosted_url = ""
    if not hosted_url:
        hosted_url = _existing_hosted_property_tour_url(normalized)
    if not hosted_url:
        return normalized
    vendor_public_url = _first_non_empty_text(
        normalized.get("crezlo_public_url"),
        normalized.get("public_url"),
        normalized.get("share_url"),
    )
    normalized["hosted_url"] = hosted_url
    normalized["public_url"] = hosted_url
    if vendor_public_url:
        normalized["crezlo_public_url"] = vendor_public_url
    return normalized


def _property_tour_immersive_quality_block_reason(structured_output: dict[str, object]) -> str:
    """Return the provider quality-gate reason, if this artifact is not publishable.

    Crezlo artifacts can contain a vendor/editor URL even when the spatial
    acceptance gate rejected the output (for example, when the provider only
    produced flat JPEG scenes).  That URL must never be converted into a
    first-party gallery or treated as a ready tour.  Keep this check separate
    from the legacy fallback detector so all provider outputs fail closed.
    """
    normalized = dict(structured_output or {})
    if str(normalized.get("quality_gate_status") or "").strip().lower() == "blocked":
        return _first_non_empty_text(
            normalized.get("quality_gate_reason"),
            "crezlo_immersive_evidence_missing",
        )
    acceptance = normalized.get("immersive_acceptance_json")
    if isinstance(acceptance, dict) and acceptance and acceptance.get("accepted") is not True:
        return _first_non_empty_text(
            acceptance.get("reason"),
            "crezlo_immersive_evidence_missing",
        )
    return ""


def _property_reconstruction_asset_suffix(*, url: str, content_type: str = "") -> str:
    suffix = _hosted_property_tour_asset_suffix(url=url, content_type=content_type).lower()
    if suffix not in {".jpg", ".jpeg", ".png", ".webp", ".tif", ".tiff"}:
        suffix = ".jpg"
    return suffix


def _download_property_reconstruction_image(url: str, target_dir: Path, *, stem: str) -> Path | None:
    normalized_url = _safe_live_property_tour_url(url)
    if not normalized_url:
        return None
    initial_suffix = _property_reconstruction_asset_suffix(url=normalized_url)
    initial_path = (target_dir / f"{stem}{initial_suffix}").resolve()
    if target_dir.resolve() not in initial_path.parents:
        return None
    try:
        content_type = _download_public_tour_asset_with_type(normalized_url, initial_path)
        final_suffix = _property_reconstruction_asset_suffix(url=normalized_url, content_type=content_type)
        final_path = (target_dir / f"{stem}{final_suffix}").resolve()
        if target_dir.resolve() not in final_path.parents:
            return None
        if final_path != initial_path:
            initial_path.rename(final_path)
        return final_path if final_path.is_file() and final_path.stat().st_size > 0 else None
    except Exception:
        with contextlib.suppress(Exception):
            initial_path.unlink(missing_ok=True)
        return None


def _property_reconstruction_script_path() -> Path:
    for parent in Path(__file__).resolve().parents:
        candidate = parent / "scripts" / "generate_property_reconstruction.py"
        if candidate.exists():
            return candidate.resolve()
    return (_repo_root() / "scripts" / "generate_property_reconstruction.py").resolve()


def _property_reconstruction_render_bridge_url() -> str:
    configured = str(os.getenv("PROPERTYQUARRY_RECONSTRUCTION_RENDER_BRIDGE_URL") or "").strip()
    if configured:
        return configured
    return "http://propertyquarry-render-tools:8091/generate-reconstruction"


def _property_reconstruction_render_bridge_token() -> str:
    return str(os.getenv("PROPERTYQUARRY_RECONSTRUCTION_RENDER_BRIDGE_TOKEN") or "").strip()


def _property_reconstruction_generation_timeout_seconds() -> int:
    raw_value = str(os.getenv("PROPERTYQUARRY_RECONSTRUCTION_TIMEOUT_SECONDS") or "").strip()
    try:
        parsed = int(float(raw_value or "420"))
    except Exception:
        parsed = 420
    return max(parsed, 120)


def _property_reconstruction_bundle_generation_timeout_seconds(
    *,
    skip_video: bool,
    route_stop_count: int = 0,
    photo_count: int = 0,
    room_count: int = 0,
) -> int:
    base_timeout = _property_reconstruction_generation_timeout_seconds()
    if skip_video:
        return base_timeout
    complexity = max(int(route_stop_count or 0), int(photo_count or 0), int(room_count or 0), 1)
    derived_timeout = 240 + (complexity * 60)
    return max(base_timeout, min(1800, derived_timeout))


def _property_reconstruction_request_timeout_seconds() -> int:
    generation_timeout_seconds = _property_reconstruction_generation_timeout_seconds()
    raw_value = str(os.getenv("PROPERTYQUARRY_RECONSTRUCTION_REQUEST_TIMEOUT_SECONDS") or "").strip()
    try:
        parsed = int(float(raw_value or str(generation_timeout_seconds + 60)))
    except Exception:
        parsed = generation_timeout_seconds + 60
    return max(parsed, generation_timeout_seconds + 30)


def _property_reconstruction_should_use_render_bridge(*, skip_video: bool) -> bool:
    if _env_flag("PROPERTYQUARRY_GENERATED_RECONSTRUCTION_FORCE_RENDER_BRIDGE", default=False):
        return bool(_property_reconstruction_render_bridge_url())
    if skip_video:
        return False
    return not bool(shutil.which("ffmpeg")) and bool(_property_reconstruction_render_bridge_url())


def _stage_property_reconstruction_source_image(source_path: Path | None, stage_dir: Path, *, stem: str) -> Path | None:
    if source_path is None:
        return None
    try:
        resolved_source = Path(source_path).expanduser().resolve()
    except Exception:
        return None
    if not resolved_source.is_file():
        return None
    suffix = resolved_source.suffix.lower()
    if suffix not in {".jpg", ".jpeg", ".png", ".webp", ".tif", ".tiff"}:
        suffix = ".jpg"
    staged_path = (stage_dir / f"{stem}{suffix}").resolve()
    if stage_dir.resolve() not in staged_path.parents:
        return None
    if staged_path != resolved_source:
        shutil.copy2(resolved_source, staged_path)
    return staged_path if staged_path.is_file() and staged_path.stat().st_size > 0 else None


def _stage_property_reconstruction_layout_contract(
    source: object,
    stage_dir: Path,
) -> Path | None:
    """Stage a reviewed floorplan-analysis JSON beside the source floorplan."""
    target = (stage_dir / "floorplan-analysis.json").resolve()
    if stage_dir.resolve() not in target.parents:
        return None
    if isinstance(source, dict):
        try:
            target.write_text(json.dumps(source, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        except (OSError, TypeError, ValueError):
            return None
        return target if target.is_file() and target.stat().st_size > 0 else None
    raw_path = str(source or "").strip()
    if not raw_path:
        return None
    try:
        resolved_source = Path(raw_path).expanduser().resolve()
    except Exception:
        return None
    if not resolved_source.is_file() or resolved_source.suffix.lower() != ".json":
        return None
    try:
        shutil.copy2(resolved_source, target)
    except OSError:
        return None
    return target if target.is_file() and target.stat().st_size > 0 else None


def _run_property_reconstruction_render_bridge(
    *,
    slug: str,
    floorplan_path: Path | None,
    photo_paths: list[Path],
    style_label: str,
    room_count: int,
    route_labels: list[str],
    skip_video: bool,
    floorplan_analysis_path: Path | None = None,
) -> dict[str, object]:
    bridge_url = _property_reconstruction_render_bridge_url()
    if not bridge_url:
        raise RuntimeError("property_reconstruction_render_bridge_url_missing")
    walkthrough_seconds_per_stop_raw = str(
        os.getenv("PROPERTYQUARRY_RECONSTRUCTION_WALKTHROUGH_SECONDS_PER_STOP") or ""
    ).strip()
    try:
        walkthrough_seconds_per_stop = float(walkthrough_seconds_per_stop_raw or "0")
    except Exception:
        walkthrough_seconds_per_stop = 0.0
    try:
        selected_style = reconstruction_style(style_label)
    except ValueError as exc:
        raise RuntimeError("property_reconstruction_style_unsupported") from exc
    payload = {
        "slug": str(slug or "").strip(),
        "skip_video": bool(skip_video),
        "floorplan_path": str(floorplan_path) if floorplan_path is not None else "",
        "floorplan_analysis_path": str(floorplan_analysis_path) if floorplan_analysis_path is not None else "",
        "photo_paths": [str(path) for path in photo_paths if isinstance(path, Path)],
        "style_label": style_label,
        "style_id": str(selected_style.get("id") or ""),
        "style_signature": str(selected_style.get("signature") or ""),
        "room_count": max(0, int(room_count or 0)),
        "route_labels": [str(label or "").strip() for label in route_labels if str(label or "").strip()],
        "timeout_seconds": _property_reconstruction_generation_timeout_seconds(),
    }
    if walkthrough_seconds_per_stop > 0.0:
        payload["walkthrough_seconds_per_stop"] = walkthrough_seconds_per_stop
    request = urllib.request.Request(
        bridge_url,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "User-Agent": "PropertyQuarry reconstruction service",
        },
        method="POST",
    )
    token = _property_reconstruction_render_bridge_token()
    if token:
        request.add_header("Authorization", f"Bearer {token}")
    timeout_seconds = _property_reconstruction_request_timeout_seconds()
    try:
        with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
            raw = response.read().decode("utf-8", errors="replace")
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(
            "property_reconstruction_render_bridge_http_error:"
            + compact_text(f"{exc.code}:{detail}".strip(), fallback="bridge request failed", limit=260)
        ) from exc
    except Exception as exc:
        raise RuntimeError(
            "property_reconstruction_render_bridge_unreachable:"
            + compact_text(str(exc), fallback=type(exc).__name__, limit=260)
        ) from exc
    try:
        loaded = json.loads(raw or "{}")
    except Exception as exc:
        raise RuntimeError(
            "property_reconstruction_render_bridge_invalid_json:"
            + compact_text(raw.strip(), fallback="invalid bridge response", limit=260)
        ) from exc
    if not isinstance(loaded, dict):
        raise RuntimeError("property_reconstruction_render_bridge_invalid_response")
    if str(loaded.get("status") or "").strip() != "generated":
        detail = _first_non_empty_text(loaded.get("reason"), loaded.get("detail"), raw)
        raise RuntimeError(
            "property_reconstruction_render_bridge_failed:"
            + compact_text(detail, fallback="bridge render failed", limit=260)
        )
    return loaded


def _write_generated_reconstruction_property_tour_bundle_unchecked(
    *,
    principal_id: str,
    title: str,
    listing_id: str,
    property_url: str,
    variant_key: str,
    media_urls: list[str] | tuple[str, ...],
    floorplan_urls: list[str] | tuple[str, ...],
    property_facts_json: dict[str, object],
    source_host: str,
    source_ref: str = "",
    external_id: str = "",
    recipient_email: str = "",
    diorama_style_hint: str = "",
    search_run_id: object = "",
) -> dict[str, object]:
    normalized_principal = str(principal_id or "").strip()
    if not normalized_principal:
        raise RuntimeError("hosted_property_tour_principal_required")
    try:
        selected_reconstruction_style = reconstruction_style(
            str(diorama_style_hint or "").strip()
        )
    except ValueError as exc:
        raise RuntimeError("property_reconstruction_style_unsupported") from exc
    normalized_search_run_id = str(search_run_id or "").strip()
    normalized_floorplans = [
        _safe_live_property_tour_url(value)
        for value in list(floorplan_urls or [])
        if _safe_live_property_tour_url(value)
    ]
    normalized_media = [
        _safe_live_property_tour_url(value)
        for value in list(media_urls or [])
        if _safe_live_property_tour_url(value) and _safe_live_property_tour_url(value) not in set(normalized_floorplans)
    ]
    if not normalized_floorplans and not normalized_media:
        raise RuntimeError("reconstruction_source_assets_missing")
    public_dir = _public_tour_dir()
    base_url = _hosted_property_tour_public_base_url()
    slug = _make_hosted_property_tour_slug(
        title=title,
        listing_id=listing_id,
        property_url=property_url,
        variant_key=variant_key,
        principal_id=normalized_principal,
    )
    _assert_governed_property_tour_slug_not_reserved(slug)
    legacy_slug = _make_hosted_property_tour_slug(
        title=title,
        listing_id=listing_id,
        property_url=property_url,
        variant_key=variant_key,
    )
    tour_url = f"{base_url}/{slug}"
    bundle_dir = public_dir / slug
    existing_payload = _existing_owned_hosted_property_tour_payload(
        slug=slug,
        legacy_slug=legacy_slug,
        principal_id=normalized_principal,
    )
    existing_reconstruction = (
        existing_payload.get("generated_reconstruction")
        if isinstance(existing_payload.get("generated_reconstruction"), dict)
        else {}
    )
    if (
        existing_payload
        and _hosted_property_tour_generated_reconstruction_bundle_ready(tour_url)
        and _property_reconstruction_style_cache_matches(
            existing_reconstruction,
            requested_style=selected_reconstruction_style,
        )
    ):
        _normalize_generated_reconstruction_bundle_permissions(bundle_dir)
        return existing_payload
    bundle_dir.mkdir(parents=True, exist_ok=True)
    facts = dict(property_facts_json or {})
    facts.update(
        {
            "has_floorplan": bool(facts.get("has_floorplan") or normalized_floorplans),
            "floorplan_count": max(int(facts.get("floorplan_count") or 0), len(normalized_floorplans)),
            "floorplan_urls_json": normalized_floorplans,
            "tour_media_mode": "generated_reconstruction",
            "source_media_count": len(normalized_media),
            "address_lines": [str(source_host or "").strip()] if source_host and not facts.get("address_lines") else facts.get("address_lines", []),
        }
    )
    display_title = compact_text(title, fallback="Property layout preview", limit=180)
    reconstruction_room_count = 0
    reconstruction_route_labels: list[str] = []
    with contextlib.suppress(Exception):
        reconstruction_room_count, reconstruction_route_labels = _magicfit_property_room_visit_plan(
            title=display_title,
            property_facts=facts,
        )
    normalized_reconstruction_route_labels = [
        compact_text(str(label or "").strip(), fallback="", limit=80)
        for label in reconstruction_route_labels
        if compact_text(str(label or "").strip(), fallback="", limit=80)
    ]
    if normalized_reconstruction_route_labels:
        facts["magicfit_route_labels"] = list(normalized_reconstruction_route_labels)
        facts["room_visit_plan"] = list(normalized_reconstruction_route_labels)
        existing_scene_count = 0
        with contextlib.suppress(Exception):
            existing_scene_count = int(float(str(facts.get("tour_scene_count") or 0).strip()))
        facts["tour_scene_count"] = max(existing_scene_count, len(normalized_reconstruction_route_labels))
    payload = dict(existing_payload or {})
    payload.update(
        {
            "slug": slug,
            "hosted_url": tour_url,
            "public_url": tour_url,
            "principal_id": normalized_principal,
            "search_run_id": normalized_search_run_id,
            "listing_url": property_url,
            "property_url": property_url,
            "source_ref": str(source_ref or "").strip(),
            "external_id": str(external_id or "").strip(),
            "recipient_email": str(recipient_email or "").strip().lower(),
            "title": f"{display_title} - generated layout preview",
            "display_title": display_title,
            "tour_title": f"{display_title} - generated layout preview",
            "tour_id": payload.get("tour_id"),
            "variant_key": variant_key,
            "variant_label": "generated layout preview",
            "scene_strategy": "generated_reconstruction",
            "scene_count": max(1, len(normalized_media) + int(bool(normalized_floorplans))),
            "facts": facts,
            "brief": {
                "theme_name": "generated_reconstruction",
                "tour_style": "floorplan_photo_reconstruction",
                "audience": "property_screening",
                "creative_brief": "Build an internal layout preview from the source floorplan and listing photos.",
                "call_to_action": "Use the layout preview only as a non-authoritative planning aid.",
            },
            "editor_url": "",
            "crezlo_public_url": "",
            "scenes": payload.get("scenes") or [],
            "generated_at": _now_iso(),
            "creation_mode": "generated_reconstruction_tour",
            "publication_status": "generating",
        }
    )
    manifest_path = bundle_dir / "tour.json"
    _write_hosted_property_tour_payload(bundle_dir, payload)
    script_path = _property_reconstruction_script_path()
    if not script_path.exists():
        raise RuntimeError("property_reconstruction_script_missing")
    skip_video = _env_flag("PROPERTYQUARRY_GENERATED_RECONSTRUCTION_SKIP_VIDEO", default=False)
    with tempfile.TemporaryDirectory(prefix="propertyquarry-reconstruction-source-", dir=str(bundle_dir)) as tmp_dir:
        tmp_path = Path(tmp_dir)
        floorplan_path: Path | None = None
        for index, floorplan_url in enumerate(normalized_floorplans[:3], start=1):
            downloaded_floorplan = _download_property_reconstruction_image(
                floorplan_url,
                tmp_path,
                stem=f"floorplan-{index:02d}",
            )
            floorplan_path = _stage_property_reconstruction_source_image(
                downloaded_floorplan,
                tmp_path,
                stem=f"floorplan-{index:02d}",
            )
            if floorplan_path is not None:
                break
        photo_paths: list[Path] = []
        for index, media_url in enumerate(normalized_media[:8], start=1):
            downloaded_photo = _download_property_reconstruction_image(
                media_url,
                tmp_path,
                stem=f"photo-{index:02d}",
            )
            photo_path = _stage_property_reconstruction_source_image(
                downloaded_photo,
                tmp_path,
                stem=f"photo-{index:02d}",
            )
            if photo_path is not None:
                photo_paths.append(photo_path)
        floorplan_analysis_path = _stage_property_reconstruction_layout_contract(
            facts.get("floorplan_analysis_json") or facts.get("floorplan_analysis_path"),
            tmp_path,
        )
        if floorplan_path is None and not photo_paths:
            raise RuntimeError("reconstruction_source_assets_unavailable")
        style_label = str(selected_reconstruction_style.get("prompt") or "")
        style_id = str(selected_reconstruction_style.get("id") or "")
        style_signature = str(selected_reconstruction_style.get("signature") or "")
        if _property_reconstruction_should_use_render_bridge(skip_video=skip_video):
            bridge_kwargs: dict[str, object] = {
                "slug": slug,
                "floorplan_path": floorplan_path,
                "photo_paths": photo_paths,
                "style_label": style_label,
                "room_count": reconstruction_room_count,
                "route_labels": normalized_reconstruction_route_labels,
                "skip_video": skip_video,
            }
            # Keep test/extension adapters that implement the pre-contract
            # bridge signature usable while the production bridge receives the
            # measured layout artifact whenever it advertises the parameter.
            try:
                bridge_parameters = inspect.signature(_run_property_reconstruction_render_bridge).parameters
            except (TypeError, ValueError):
                bridge_parameters = {}
            if "floorplan_analysis_path" in bridge_parameters:
                bridge_kwargs["floorplan_analysis_path"] = floorplan_analysis_path
            _run_property_reconstruction_render_bridge(**bridge_kwargs)
        else:
            command = [
                _runtime_python_executable(),
                str(script_path),
                "--slug",
                slug,
            ]
            if skip_video:
                command.append("--skip-video")
            if floorplan_path is not None:
                command.extend(["--floorplan", str(floorplan_path)])
            else:
                command.append("--infer-floorplan-from-photos")
            if floorplan_analysis_path is not None:
                command.extend(["--floorplan-analysis", str(floorplan_analysis_path)])
            for photo_path in photo_paths:
                command.extend(["--photo", str(photo_path)])
            if style_label:
                command.extend(["--style-label", style_label])
            command.extend(
                [
                    "--style-id",
                    style_id,
                    "--style-signature",
                    style_signature,
                ]
            )
            if reconstruction_room_count > 0:
                command.extend(["--room-count", str(int(reconstruction_room_count))])
            for route_label in normalized_reconstruction_route_labels:
                command.extend(["--room-label", route_label])
            completed = subprocess.run(
                command,
                cwd=str(script_path.parent.parent if script_path.parent.name == "scripts" else _repo_root()),
                capture_output=True,
                text=True,
                timeout=_property_reconstruction_bundle_generation_timeout_seconds(
                    skip_video=skip_video,
                    route_stop_count=len(normalized_reconstruction_route_labels),
                    photo_count=len(photo_paths),
                    room_count=reconstruction_room_count,
                ),
                check=False,
            )
            if completed.returncode != 0:
                raise RuntimeError(
                    "property_reconstruction_generation_failed:"
                    + compact_text((completed.stderr or completed.stdout or "").strip(), fallback="generator failed", limit=260)
                )
    try:
        generated_payload_raw = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception:
        generated_payload_raw = {}
    generated_payload = generated_payload_raw if isinstance(generated_payload_raw, dict) else {}
    generated_reconstruction = (
        generated_payload.get("generated_reconstruction")
        if isinstance(generated_payload.get("generated_reconstruction"), dict)
        else {}
    )
    bundle_root = bundle_dir.resolve()
    expected_style_id = str(selected_reconstruction_style.get("id") or "")
    expected_style_signature = str(selected_reconstruction_style.get("signature") or "")
    if (
        str(generated_reconstruction.get("viewer_version") or "")
        != _PROPERTY_RECONSTRUCTION_VIEWER_VERSION
        or str(generated_reconstruction.get("style_id") or "") != expected_style_id
        or str(generated_reconstruction.get("style_signature") or "") != expected_style_signature
        or str(generated_reconstruction.get("style_evidence_status") or "") != "ready"
    ):
        raise RuntimeError("property_reconstruction_style_contract_mismatch")
    reconstruction_relpath = _hosted_property_tour_safe_asset_relpath(
        str(generated_reconstruction.get("manifest_relpath") or "").strip()
    )
    reconstruction_path = (
        (bundle_dir / reconstruction_relpath).resolve()
        if reconstruction_relpath
        else bundle_dir / "__missing_reconstruction_receipt__"
    )
    if (
        not reconstruction_relpath
        or bundle_root not in reconstruction_path.parents
        or not reconstruction_path.is_file()
    ):
        raise RuntimeError("property_reconstruction_style_receipt_missing")
    try:
        reconstruction_receipt_raw = json.loads(reconstruction_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError("property_reconstruction_style_receipt_invalid") from exc
    reconstruction_receipt = (
        reconstruction_receipt_raw
        if isinstance(reconstruction_receipt_raw, dict)
        else {}
    )
    receipt_requested_style = (
        reconstruction_receipt.get("requested_style")
        if isinstance(reconstruction_receipt.get("requested_style"), dict)
        else {}
    )
    receipt_style_scene = (
        reconstruction_receipt.get("style_scene")
        if isinstance(reconstruction_receipt.get("style_scene"), dict)
        else {}
    )
    style_scene_ready, _style_scene_reason = validate_style_scene(
        receipt_style_scene,
        expected_style=selected_reconstruction_style,
    )
    if (
        not style_scene_ready
        or str(receipt_requested_style.get("id") or "") != expected_style_id
        or str(receipt_requested_style.get("signature") or "") != expected_style_signature
        or str(receipt_style_scene.get("scene_signature") or "")
        != str(generated_reconstruction.get("style_scene_signature") or "")
    ):
        raise RuntimeError("property_reconstruction_style_evidence_invalid")
    walkthrough_relpath = _hosted_property_tour_safe_asset_relpath(
        str(generated_reconstruction.get("walkthrough_video_relpath") or "").strip()
    )
    walkthrough_path = (bundle_dir / walkthrough_relpath).resolve() if walkthrough_relpath else bundle_dir / "__missing_walkthrough__"
    if not walkthrough_relpath or bundle_root not in walkthrough_path.parents or not walkthrough_path.is_file():
        raise RuntimeError("property_reconstruction_walkthrough_missing")
    walkthrough_sidecar_relpath = _hosted_property_tour_safe_asset_relpath(
        str(generated_reconstruction.get("walkthrough_sidecar_relpath") or "").strip()
    )
    walkthrough_sidecar_path = (
        (bundle_dir / walkthrough_sidecar_relpath).resolve()
        if walkthrough_sidecar_relpath
        else bundle_dir / "__missing_walkthrough_sidecar__"
    )
    if not walkthrough_sidecar_relpath or bundle_root not in walkthrough_sidecar_path.parents or not walkthrough_sidecar_path.is_file():
        raise RuntimeError("property_reconstruction_walkthrough_sidecar_missing")
    if str(generated_payload.get("video_relpath") or "").strip() != walkthrough_relpath:
        raise RuntimeError("property_reconstruction_walkthrough_contract_missing")
    if str(generated_payload.get("video_sidecar_relpath") or "").strip() != walkthrough_sidecar_relpath:
        raise RuntimeError("property_reconstruction_walkthrough_sidecar_contract_missing")
    if str(generated_payload.get("video_provider") or "").strip() != "propertyquarry_generated_reconstruction":
        raise RuntimeError("property_reconstruction_walkthrough_provider_missing")
    if str(generated_payload.get("video_provider_key") or "").strip() != "propertyquarry_generated_reconstruction":
        raise RuntimeError("property_reconstruction_walkthrough_provider_key_missing")
    if str(generated_payload.get("video_coverage_proof") or "").strip() != "boundary_verified_frame_continuation":
        raise RuntimeError("property_reconstruction_walkthrough_coverage_missing")
    viewer_relpath = str(generated_reconstruction.get("viewer_relpath") or "").strip().replace("\\", "/").lstrip("/")
    viewer_path = (bundle_dir / viewer_relpath).resolve() if viewer_relpath else bundle_dir / "__missing_viewer__"
    if not viewer_relpath or bundle_root not in viewer_path.parents or not viewer_path.is_file():
        raise RuntimeError("property_reconstruction_viewer_missing")
    _normalize_generated_reconstruction_bundle_permissions(bundle_dir)
    return _load_hosted_property_tour_payload(
        bundle_dir,
        principal_id=normalized_principal,
    )


