def _write_generated_reconstruction_property_tour_bundle_with_lock_held(
    *,
    principal_id: str,
    title: str,
    listing_id: str,
    property_url: str,
    variant_key: str,
    media_urls: list[str] | tuple[str, ...],
    floorplan_urls: list[str] | tuple[str, ...],
    property_facts_json: dict[str, object],
    source_host: str,
    source_ref: str = "",
    external_id: str = "",
    recipient_email: str = "",
    diorama_style_hint: str = "",
    search_run_id: object = "",
) -> dict[str, object]:
    """Publish a generated reconstruction transactionally for catchable exits.

    The renderer needs the canonical bundle path while it works.  Keep that
    in-progress manifest fail-closed, preserve any prior owned bundle by
    rename, and either finalize a ready publication or restore the exact
    previous tree.  Directory fsyncs make the rename intent durable where the
    platform supports them; this does not claim power-loss or SIGKILL recovery.
    """

    normalized_principal = str(principal_id or "").strip()
    if not normalized_principal:
        raise RuntimeError("hosted_property_tour_principal_required")
    try:
        selected_reconstruction_style = reconstruction_style(
            str(diorama_style_hint or "").strip()
        )
    except ValueError as exc:
        raise RuntimeError("property_reconstruction_style_unsupported") from exc
    normalized_search_run_id = str(search_run_id or "").strip()
    public_dir = _public_tour_dir()
    public_dir.mkdir(parents=True, exist_ok=True)
    if public_dir.is_symlink() or not public_dir.is_dir():
        raise RuntimeError("property_reconstruction_public_root_invalid")
    public_dir = public_dir.resolve()
    slug = _make_hosted_property_tour_slug(
        title=title,
        listing_id=listing_id,
        property_url=property_url,
        variant_key=variant_key,
        principal_id=normalized_principal,
    )
    _assert_governed_property_tour_slug_not_reserved(slug)
    bundle_dir = public_dir / slug
    tour_url = f"{_hosted_property_tour_public_base_url()}/{slug}"
    legacy_slug = _make_hosted_property_tour_slug(
        title=title,
        listing_id=listing_id,
        property_url=property_url,
        variant_key=variant_key,
    )
    existing_payload = _existing_owned_hosted_property_tour_payload(
        slug=slug,
        legacy_slug=legacy_slug,
        principal_id=normalized_principal,
    )
    existing_reconstruction = (
        existing_payload.get("generated_reconstruction")
        if isinstance(existing_payload.get("generated_reconstruction"), dict)
        else {}
    )
    if (
        existing_payload
        and bundle_dir.is_dir()
        and _hosted_property_tour_generated_reconstruction_bundle_ready(tour_url)
        and _property_reconstruction_style_cache_matches(
            existing_reconstruction,
            requested_style=selected_reconstruction_style,
        )
    ):
        with _property_search_storage.property_account_publication_authority(
            normalized_principal,
            run_id=normalized_search_run_id,
        ):
            return existing_payload

    # Keep rollback transactions on the same mounted filesystem as canonical
    # bundles so every os.replace remains atomic.  The leading dot keeps this
    # directory outside the public slug namespace: routed tour slugs must begin
    # with an ASCII alphanumeric character.
    control_root = public_dir / ".publication-control"
    if control_root.is_symlink():
        raise RuntimeError("property_reconstruction_publication_control_invalid")
    control_root.mkdir(mode=0o700, exist_ok=True)
    control_root.chmod(0o700)
    transactions_root = control_root / "transactions"
    if transactions_root.is_symlink():
        raise RuntimeError("property_reconstruction_publication_control_invalid")
    transactions_root.mkdir(mode=0o700, exist_ok=True)
    transactions_root.chmod(0o700)
    transaction_dir = Path(
        tempfile.mkdtemp(
            prefix=f"{slug}.",
            dir=str(transactions_root),
        )
    )
    transaction_dir.chmod(0o700)
    backup_dir = transaction_dir / "previous-bundle"
    failed_dir = transaction_dir / "failed-bundle"
    bundle_existed = bundle_dir.exists()

    def _fsync_directory(path: Path) -> None:
        descriptor = -1
        try:
            descriptor = os.open(
                path,
                os.O_RDONLY
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_NOFOLLOW", 0),
            )
            os.fsync(descriptor)
        finally:
            if descriptor >= 0:
                os.close(descriptor)

    def _move_failed_bundle_out_of_public_path() -> None:
        if not (bundle_dir.exists() or bundle_dir.is_symlink()):
            return
        try:
            os.replace(bundle_dir, failed_dir)
        except Exception as exc:
            raise RuntimeError(
                f"property_reconstruction_rollback_failed:quarantine:{transaction_dir}"
            ) from exc
        _fsync_directory(public_dir)
        _fsync_directory(transaction_dir)

    def _restore_previous_bundle() -> None:
        if bundle_existed:
            # backup_dir existing is the filesystem evidence that the prior
            # bundle was moved successfully, including when an interruption
            # is raised immediately after os.replace performs the rename.
            if backup_dir.exists() or backup_dir.is_symlink():
                _move_failed_bundle_out_of_public_path()
                try:
                    os.replace(backup_dir, bundle_dir)
                except Exception as exc:
                    raise RuntimeError(
                        f"property_reconstruction_rollback_failed:restore:{transaction_dir}"
                    ) from exc
                _fsync_directory(transaction_dir)
                _fsync_directory(public_dir)
            # Without a backup, the initial rename did not take effect; the
            # original canonical tree remains authoritative and untouched.
            return
        _move_failed_bundle_out_of_public_path()

    transaction_resolved = False
    try:
        if bundle_existed:
            # Keep the original directory itself as the rollback authority.
            # The working copy preserves the unchecked writer's existing
            # payload/cache semantics while it mutates the canonical path.
            os.replace(bundle_dir, backup_dir)
            _fsync_directory(public_dir)
            _fsync_directory(transaction_dir)
            shutil.copytree(backup_dir, bundle_dir, symlinks=True)
            _fsync_directory(public_dir)
        _write_generated_reconstruction_property_tour_bundle_unchecked(
            principal_id=normalized_principal,
            title=title,
            listing_id=listing_id,
            property_url=property_url,
            variant_key=variant_key,
            media_urls=media_urls,
            floorplan_urls=floorplan_urls,
            property_facts_json=property_facts_json,
            source_host=source_host,
            source_ref=source_ref,
            external_id=external_id,
            recipient_email=recipient_email,
            diorama_style_hint=diorama_style_hint,
            search_run_id=normalized_search_run_id,
        )
        manifest_path = bundle_dir / "tour.json"
        try:
            finalized_payload_raw = json.loads(manifest_path.read_text(encoding="utf-8"))
        except Exception as exc:
            raise RuntimeError("property_reconstruction_publication_manifest_invalid") from exc
        if not isinstance(finalized_payload_raw, dict):
            raise RuntimeError("property_reconstruction_publication_manifest_invalid")
        finalized_payload = {
            **_owned_hosted_property_tour_private_receipt(
                bundle_dir,
                principal_id=normalized_principal,
            ),
            **dict(finalized_payload_raw),
            "principal_id": normalized_principal,
            "search_run_id": normalized_search_run_id,
        }
        # Rendering can outlive an account-erasure sweep and recreate files in
        # the canonical bundle path. Reacquire the same durable account
        # authority immediately before promotion; a recorded fence raises into
        # the existing rollback path, which removes the recreated render tree.
        with _property_search_storage.property_account_publication_authority(
            normalized_principal,
            run_id=normalized_search_run_id,
        ):
            finalized_payload["publication_status"] = "ready"
            # Commit the canonical public manifest and its owner-only receipt
            # together. The renderer adds video provenance after the initial
            # generating manifest, so rewriting only tour.json here would
            # either leak those private fields or discard them.
            _write_hosted_property_tour_payload_with_slug_lock_held(
                bundle_dir,
                finalized_payload,
                publication_authority_held=True,
            )
            if not _hosted_property_tour_generated_reconstruction_bundle_ready(tour_url):
                raise RuntimeError("property_reconstruction_publication_not_ready")
            published_payload = _load_hosted_property_tour_payload(
                bundle_dir,
                principal_id=normalized_principal,
            )
            if published_payload.get("publication_status") != "ready":
                raise RuntimeError("property_reconstruction_publication_status_invalid")
        transaction_resolved = True
        return published_payload
    except BaseException:
        _restore_previous_bundle()
        transaction_resolved = True
        raise
    finally:
        # If reconciliation itself fails, retain the private transaction tree
        # and its authoritative backup for recovery instead of deleting the
        # only intact prior copy.
        if transaction_resolved:
            shutil.rmtree(transaction_dir, ignore_errors=True)
            _fsync_directory(transactions_root)


def _write_generated_reconstruction_property_tour_bundle(
    *,
    principal_id: str,
    title: str,
    listing_id: str,
    property_url: str,
    variant_key: str,
    media_urls: list[str] | tuple[str, ...],
    floorplan_urls: list[str] | tuple[str, ...],
    property_facts_json: dict[str, object],
    source_host: str,
    source_ref: str = "",
    external_id: str = "",
    recipient_email: str = "",
    diorama_style_hint: str = "",
    search_run_id: object = "",
) -> dict[str, object]:
    normalized_principal = str(principal_id or "").strip()
    if not normalized_principal:
        raise RuntimeError("hosted_property_tour_principal_required")
    normalized_search_run_id = str(search_run_id or "").strip()
    public_dir = _public_tour_dir()
    public_dir.mkdir(parents=True, exist_ok=True)
    if public_dir.is_symlink() or not public_dir.is_dir():
        raise RuntimeError("property_reconstruction_public_root_invalid")
    public_dir = public_dir.resolve()
    slug = _make_hosted_property_tour_slug(
        title=title,
        listing_id=listing_id,
        property_url=property_url,
        variant_key=variant_key,
        principal_id=normalized_principal,
    )
    _assert_governed_property_tour_slug_not_reserved(slug)
    with _hosted_property_tour_publication_lock(public_dir=public_dir, slug=slug):
        return _write_generated_reconstruction_property_tour_bundle_with_lock_held(
            principal_id=normalized_principal,
            title=title,
            listing_id=listing_id,
            property_url=property_url,
            variant_key=variant_key,
            media_urls=media_urls,
            floorplan_urls=floorplan_urls,
            property_facts_json=property_facts_json,
            source_host=source_host,
            source_ref=source_ref,
            external_id=external_id,
            recipient_email=recipient_email,
            diorama_style_hint=diorama_style_hint,
            search_run_id=normalized_search_run_id,
        )


def _feelestate_json_rpc(method: str, params: list[object]) -> dict[str, object]:
    request = urllib.request.Request(
        "https://cms.feelestate.com/json",
        data=json.dumps({"jsonrpc": "2.0", "method": method, "params": params, "id": "1"}).encode("utf-8"),
        headers={"Content-Type": "application/json", "User-Agent": _PROPERTY_SCOUT_USER_AGENT},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=60) as response:
        payload = json.loads(response.read().decode("utf-8", "ignore"))
    if not isinstance(payload, dict) or not isinstance(payload.get("result"), dict):
        raise RuntimeError("feelestate_json_rpc_failed")
    return dict(payload["result"])


def _hosted_property_tour_video_delivery(tour_url: str) -> dict[str, object]:
    normalized_url = str(tour_url or "").strip()
    if not normalized_url:
        return {}
    parsed = urllib.parse.urlparse(normalized_url)
    path_parts = [part for part in str(parsed.path or "").split("/") if part]
    if len(path_parts) < 2 or path_parts[-2] != "tours":
        return {}
    slug = str(path_parts[-1] or "").strip()
    if not slug:
        return {}
    public_dir = Path(str(os.getenv("EA_PUBLIC_TOUR_DIR") or "/docker/property/state/public_property_tours")).expanduser()
    bundle_dir = public_dir / slug
    manifest_path = bundle_dir / "tour.json"
    if not manifest_path.exists():
        return {}
    try:
        payload = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    if not isinstance(payload, dict):
        return {}
    try:
        from scripts.property_magicfit_public_eligibility import (
            evaluate_magicfit_public_eligibility,
            magicfit_provider_declared,
        )
    except ModuleNotFoundError:
        from property_magicfit_public_eligibility import (  # type: ignore[no-redef]
            evaluate_magicfit_public_eligibility,
            magicfit_provider_declared,
        )
    magicfit_footprint = bool(
        magicfit_provider_declared(payload)
        or isinstance(payload.get("magicfit_import"), dict)
        or str(payload.get("video_sidecar_relpath") or "").strip().startswith(".magicfit-deliveries/")
        or str(payload.get("video_relpath") or "").strip().startswith("magicfit-media/")
    )
    magicfit_eligibility = (
        evaluate_magicfit_public_eligibility(bundle_dir, payload)
        if magicfit_footprint
        else None
    )
    if magicfit_footprint and not (
        magicfit_eligibility is not None
        and magicfit_eligibility.declared
        and magicfit_eligibility.eligible
        and magicfit_eligibility.video_relpath
    ):
        return {}
    generated_reconstruction = (
        dict(payload.get("generated_reconstruction") or {})
        if isinstance(payload.get("generated_reconstruction"), dict)
        else {}
    )
    generated_walkthrough_relpath = _hosted_property_tour_safe_asset_relpath(
        str(generated_reconstruction.get("walkthrough_video_relpath") or "").strip()
    )
    generated_sidecar_relpath = _hosted_property_tour_safe_asset_relpath(
        str(generated_reconstruction.get("walkthrough_sidecar_relpath") or "").strip()
    )
    generated_coverage = (
        dict(generated_reconstruction.get("walkthrough_coverage_proof") or {})
        if isinstance(generated_reconstruction.get("walkthrough_coverage_proof"), dict)
        else {}
    )
    generated_walkthrough_ready = bool(
        generated_walkthrough_relpath and str(generated_coverage.get("status") or "").strip().lower() == "pass"
    )
    video_relpath = (
        str(magicfit_eligibility.video_relpath)
        if magicfit_eligibility is not None
        else str(payload.get("video_relpath") or "").strip()
    )
    if not video_relpath and generated_walkthrough_ready:
        video_relpath = generated_walkthrough_relpath
    if not video_relpath:
        return {}
    video_provider = str(
        payload.get("video_provider")
        or payload.get("video_provider_key")
        or payload.get("video_render_provider")
        or ("propertyquarry_generated_reconstruction" if generated_walkthrough_ready else "")
    ).strip().lower()
    local_video_path = (bundle_dir / video_relpath).resolve()
    if bundle_dir.resolve() not in local_video_path.parents:
        return {}
    if not local_video_path.exists() or not local_video_path.is_file():
        return {}
    public_video_url = (
        _hosted_property_tour_walkthrough_asset_url(normalized_url)
        if magicfit_eligibility is not None
        else _hosted_public_tour_asset_url(normalized_url, slug=slug, asset_relpath=video_relpath)
    )
    if magicfit_eligibility is not None and not public_video_url:
        return {}
    scenes = list(payload.get("scenes") or []) if isinstance(payload.get("scenes"), list) else []
    scene_count = int(payload.get("scene_count") or len(scenes) or 0)
    sidecar_payload: dict[str, object] = {}
    sidecar_relpath = _hosted_property_tour_safe_asset_relpath(str(payload.get("video_sidecar_relpath") or "").strip())
    if not sidecar_relpath and generated_walkthrough_ready:
        sidecar_relpath = generated_sidecar_relpath
    if sidecar_relpath:
        sidecar_path = (bundle_dir / sidecar_relpath).resolve()
        if bundle_dir.resolve() in sidecar_path.parents and sidecar_path.exists() and sidecar_path.is_file():
            try:
                parsed_sidecar = json.loads(sidecar_path.read_text(encoding="utf-8"))
                if isinstance(parsed_sidecar, dict):
                    sidecar_payload = parsed_sidecar
            except Exception:
                sidecar_payload = {}
    duration_seconds = _video_duration_seconds(str(local_video_path))
    if duration_seconds <= 0.0:
        sidecar_duration_seconds = 0.0
        try:
            sidecar_duration_seconds = max(0.0, float(sidecar_payload.get("duration_seconds") or 0.0))
        except Exception:
            sidecar_duration_seconds = 0.0
        if sidecar_duration_seconds <= 0.0:
            coverage_payload = (
                dict(sidecar_payload.get("walkthrough_coverage_proof") or {})
                if isinstance(sidecar_payload.get("walkthrough_coverage_proof"), dict)
                else {}
            )
            coverage_segments = list(coverage_payload.get("coverage_segments") or [])
            for segment in coverage_segments:
                if not isinstance(segment, dict):
                    continue
                try:
                    sidecar_duration_seconds = max(sidecar_duration_seconds, float(segment.get("end") or 0.0))
                except Exception:
                    continue
        duration_seconds = sidecar_duration_seconds
    coverage_proof = ""
    payload_coverage_proof = str(payload.get("video_coverage_proof") or "").strip()
    if not payload_coverage_proof and generated_walkthrough_ready:
        payload_coverage_proof = "boundary_verified_frame_continuation"
    if payload_coverage_proof in {"boundary_verified_frame_continuation", "continuous_first_person_walkthrough"}:
        coverage_proof = payload_coverage_proof
    else:
        composition = str(sidecar_payload.get("composition") or "").strip()
        if composition in {"boundary_verified_frame_continuation", "continuous_first_person_walkthrough"}:
            coverage_proof = composition
    route_labels: list[str] = []
    route_sources = [sidecar_payload] if coverage_proof else []
    for source_payload in route_sources:
        for key in ("covered_route_labels", "magicfit_route_labels", "room_visit_plan", "route_labels", "walkthrough_route_labels"):
            raw_labels = source_payload.get(key)
            if not isinstance(raw_labels, (list, tuple)):
                continue
            for raw_label in raw_labels:
                label = compact_text(str(raw_label or "").strip(), fallback="", limit=80)
                if label and label.lower() not in {item.lower() for item in route_labels}:
                    route_labels.append(label)
    if not route_labels and coverage_proof:
        raw_labels = payload.get("covered_route_labels") or payload.get("magicfit_route_labels")
        if not isinstance(raw_labels, (list, tuple)):
            raw_labels = []
        for raw_label in raw_labels:
            label = compact_text(str(raw_label or "").strip(), fallback="", limit=80)
            if label and label.lower() not in {item.lower() for item in route_labels}:
                route_labels.append(label)
    return {
        "slug": slug,
        "video_url": public_video_url,
        "flythrough_url": _hosted_property_tour_walkthrough_asset_url(normalized_url),
        "video_file_path": "" if magicfit_eligibility is not None else str(local_video_path),
        "audio_probe_ref": public_video_url if magicfit_eligibility is not None else str(local_video_path),
        "provider_key": video_provider,
        "duration_seconds": duration_seconds,
        "tour_scene_count": scene_count,
        "coverage_proof": coverage_proof,
        "video_sidecar_relpath": sidecar_relpath,
        "covered_route_labels": route_labels,
        "magicfit_route_labels": route_labels,
    }


def _hosted_property_tour_scene_count(tour_url: str) -> int:
    normalized_url = str(tour_url or "").strip()
    if not normalized_url:
        return 0
    slug, bundle_dir = _hosted_property_tour_bundle_dir(normalized_url)
    if not slug or bundle_dir is None:
        return 0
    manifest_path = bundle_dir / "tour.json"
    if not manifest_path.exists():
        return 0
    try:
        payload = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception:
        return 0
    if not isinstance(payload, dict):
        return 0
    scenes = list(payload.get("scenes") or []) if isinstance(payload.get("scenes"), list) else []
    try:
        return max(0, int(payload.get("scene_count") or len(scenes) or 0))
    except Exception:
        return len(scenes)


def _hosted_property_tour_bundle_dir(tour_url: str) -> tuple[str, Path] | tuple[str, None]:
    normalized_url = str(tour_url or "").strip()
    if not normalized_url:
        return ("", None)
    slug = _hosted_property_tour_slug_from_url(normalized_url).lower()
    if re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,126}[a-z0-9])?", slug) is None:
        return ("", None)
    public_dir = Path(str(os.getenv("EA_PUBLIC_TOUR_DIR") or "/docker/property/state/public_property_tours")).expanduser()
    bundle_dir = public_dir / slug
    if not bundle_dir.exists() or not bundle_dir.is_dir():
        return (slug, None)
    return (slug, bundle_dir)


def _update_hosted_property_tour_magicfit_video_manifest(
    *,
    tour_url: str,
    video_relpath: str,
    sidecar_relpath: str,
    route_labels: list[str] | tuple[str, ...] = (),
) -> dict[str, object]:
    slug, bundle_dir = _hosted_property_tour_bundle_dir(tour_url)
    if not slug or bundle_dir is None:
        raise RuntimeError("hosted_property_tour_bundle_missing")
    manifest_path = bundle_dir / "tour.json"
    if not manifest_path.exists():
        raise RuntimeError("hosted_property_tour_manifest_missing")
    try:
        payload = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError("hosted_property_tour_manifest_invalid") from exc
    if not isinstance(payload, dict):
        raise RuntimeError("hosted_property_tour_manifest_invalid")
    normalized_video_relpath = str(video_relpath or "").strip().lstrip("/")
    normalized_sidecar_relpath = str(sidecar_relpath or "").strip().lstrip("/")
    if not normalized_video_relpath:
        raise RuntimeError("hosted_property_tour_video_relpath_missing")
    payload["video_relpath"] = normalized_video_relpath
    payload.pop("video_fallback_relpath", None)
    payload["video_provider_key"] = "magicfit"
    payload["video_provider"] = "magicfit"
    payload["video_render_provider"] = "magicfit"
    payload["video_source"] = "magicfit"
    if normalized_sidecar_relpath:
        payload["video_sidecar_relpath"] = normalized_sidecar_relpath
    normalized_route_labels = [
        compact_text(str(label or "").strip(), fallback="", limit=80)
        for label in list(route_labels or [])
        if compact_text(str(label or "").strip(), fallback="", limit=80)
    ]
    if normalized_route_labels:
        payload["magicfit_route_labels"] = normalized_route_labels
        payload["covered_route_labels"] = normalized_route_labels
        payload["room_visit_plan"] = normalized_route_labels
        payload["video_coverage_proof"] = "boundary_verified_frame_continuation"
        payload["walkthrough_coverage_proof"] = {
            "status": "pass",
            "source": "magicfit_multi_segment_render",
            "segments_expected": normalized_route_labels,
            "segments_visited": normalized_route_labels,
            "coverage_segments": [
                {"segment": label, "index": index + 1}
                for index, label in enumerate(normalized_route_labels)
            ],
        }
    payload["flythrough_url"] = _hosted_public_tour_asset_url(tour_url, slug=slug, asset_relpath=normalized_video_relpath)
    staging_manifest_path = manifest_path.with_name(f".{manifest_path.name}.{uuid4().hex}.tmp")
    try:
        staging_manifest_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(staging_manifest_path, manifest_path)
    finally:
        with contextlib.suppress(OSError):
            staging_manifest_path.unlink()
    return payload


